PathwayData.put("data/reading_writing/units/L02U2.json",{"strand":"reading_writing","level":2,"cefr":"A1b","unit":2,"theme":"My Neighborhood","essential_question":"Who helps us in our community?","schema_version":"1.0","core_words":["street","mosque","market","park","hospital","library","bakery","shop","doctor","nurse","police officer","firefighter","neighbor","near"],"recycled_words":["help","kind","brave","because","sorry","excited","worried","school","book","bread","street","teacher","friend"],"rubrics":[{"id":"RW-RUBRIC-5T","title":"Analytic writing rubric","traits":[{"name":"Ideas","name_ar":"الأفكار","bands":[{"score":4,"descriptor":"My ideas are clear, interesting and fully developed with strong details.","descriptor_ar":"أفكاري واضحة وممتعة ومدعومة بتفاصيل قوية."},{"score":3,"descriptor":"My ideas are clear and have enough details.","descriptor_ar":"أفكاري واضحة ومعها تفاصيل كافية."},{"score":2,"descriptor":"My main idea is there but needs more details.","descriptor_ar":"فكرتي الرئيسية موجودة لكنها تحتاج إلى تفاصيل أكثر."},{"score":1,"descriptor":"My ideas are unclear or very few.","descriptor_ar":"أفكاري غير واضحة أو قليلة جدًا."}]},{"name":"Organization","name_ar":"التنظيم","bands":[{"score":4,"descriptor":"Clear beginning, middle and end; ideas flow with linking words.","descriptor_ar":"بداية ووسط ونهاية واضحة، والأفكار مترابطة بكلمات الربط."},{"score":3,"descriptor":"Clear order with some linking words.","descriptor_ar":"ترتيب واضح مع بعض كلمات الربط."},{"score":2,"descriptor":"Some order, but parts are mixed up.","descriptor_ar":"يوجد بعض الترتيب لكن بعض الأجزاء غير مرتبة."},{"score":1,"descriptor":"Ideas are not in order.","descriptor_ar":"الأفكار غير مرتبة."}]},{"name":"Vocabulary","name_ar":"المفردات","bands":[{"score":4,"descriptor":"I use exact, varied words, including new unit words, correctly.","descriptor_ar":"أستخدم كلمات دقيقة ومتنوعة، منها كلمات الوحدة الجديدة، بشكل صحيح."},{"score":3,"descriptor":"I use some new words correctly.","descriptor_ar":"أستخدم بعض الكلمات الجديدة بشكل صحيح."},{"score":2,"descriptor":"I use simple words; some are repeated or wrong.","descriptor_ar":"أستخدم كلمات بسيطة، وبعضها مكرر أو غير صحيح."},{"score":1,"descriptor":"I use very few words; the meaning is hard to understand.","descriptor_ar":"أستخدم كلمات قليلة جدًا ويصعب فهم المعنى."}]},{"name":"Sentence fluency","name_ar":"سلاسة الجمل","bands":[{"score":4,"descriptor":"My sentences are complete, varied in length and easy to read aloud.","descriptor_ar":"جملي كاملة ومتنوعة الطول وسهلة القراءة بصوت عالٍ."},{"score":3,"descriptor":"Most sentences are complete, with some variety.","descriptor_ar":"معظم جملي كاملة مع بعض التنويع."},{"score":2,"descriptor":"Many sentences are short or start the same way.","descriptor_ar":"كثير من جملي قصيرة أو تبدأ بالطريقة نفسها."},{"score":1,"descriptor":"Sentences are incomplete or run together.","descriptor_ar":"جملي ناقصة أو متداخلة."}]},{"name":"Conventions","name_ar":"قواعد الكتابة","bands":[{"score":4,"descriptor":"Capitals, punctuation, spelling and grammar are almost always correct.","descriptor_ar":"الحروف الكبيرة وعلامات الترقيم والإملاء والقواعد صحيحة دائمًا تقريبًا."},{"score":3,"descriptor":"A few mistakes that do not affect meaning.","descriptor_ar":"أخطاء قليلة لا تؤثر في المعنى."},{"score":2,"descriptor":"Several mistakes; the meaning is sometimes unclear.","descriptor_ar":"عدة أخطاء، والمعنى أحيانًا غير واضح."},{"score":1,"descriptor":"Many mistakes make it hard to read.","descriptor_ar":"أخطاء كثيرة تجعل القراءة صعبة."}]}]}],"lessons":[{"id":"RW-L02-U2-LS1","title":"Word Power: My Neighborhood","lesson_type":"vocabulary","objectives":["read and say 14 neighborhood words and 2 Tier 2 words (community, safe)","break compound words into two smaller words to find their meaning (fire + fighter)","use neighborhood words to say where people work and how they help"],"objectives_ar":["قراءة ونطق 14 كلمة عن الحي وكلمتين أكاديميتين (community, safe).","تقسيم الكلمات المركبة إلى كلمتين صغيرتين لمعرفة معناها.","استخدام كلمات الحي لقول أين يعمل الناس وكيف يساعدون."],"success_criteria":["I can read and say the neighborhood words.","I can split a compound word into two words.","I can say where a helper works."],"success_criteria_ar":["أستطيع قراءة كلمات الحي ونطقها.","أستطيع تقسيم الكلمة المركبة إلى كلمتين.","أستطيع قول أين يعمل المساعد."],"map_area":"Vocabulary: Acquisition and Use","vocabulary":[{"word":"street","pos":"noun","ipa":"/strit/","definition":"a road in a town with houses or shops","arabic":"شارع","example":"Our street has many trees.","image_id":"IMG-RW-L02-U2-LS1-V01","audio_id":"AUD-RW-L02-U2-LS1-V01","tier":"core"},{"word":"mosque","pos":"noun","ipa":"/mɑsk/","definition":"a building where Muslims pray","arabic":"مسجد","example":"The mosque is near our house.","image_id":"IMG-RW-L02-U2-LS1-V02","audio_id":"AUD-RW-L02-U2-LS1-V02","tier":"core"},{"word":"market","pos":"noun","ipa":"/ˈmɑrkɪt/","definition":"a place where people buy and sell things","arabic":"سوق","example":"We buy fruit at the market.","image_id":"IMG-RW-L02-U2-LS1-V03","audio_id":"AUD-RW-L02-U2-LS1-V03","tier":"core"},{"word":"park","pos":"noun","ipa":"/pɑrk/","definition":"a green public place to play and walk","arabic":"حديقة عامة","example":"Children play in the park.","image_id":"IMG-RW-L02-U2-LS1-V04","audio_id":"AUD-RW-L02-U2-LS1-V04","tier":"core"},{"word":"hospital","pos":"noun","ipa":"/ˈhɑspɪtəl/","definition":"a place where sick people get help from doctors","arabic":"مستشفى","example":"The hospital is open all night.","image_id":"IMG-RW-L02-U2-LS1-V05","audio_id":"AUD-RW-L02-U2-LS1-V05","tier":"core"},{"word":"library","pos":"noun","ipa":"/ˈlaɪˌbrɛri/","definition":"a place with many books to borrow and read","arabic":"مكتبة","example":"I borrow books from the library.","image_id":"IMG-RW-L02-U2-LS1-V06","audio_id":"AUD-RW-L02-U2-LS1-V06","tier":"core"},{"word":"bakery","pos":"noun","ipa":"/ˈbeɪkəri/","definition":"a shop where bread and cakes are made","arabic":"مخبز","example":"The bakery smells good.","image_id":"IMG-RW-L02-U2-LS1-V07","audio_id":"AUD-RW-L02-U2-LS1-V07","tier":"core"},{"word":"shop","pos":"noun","ipa":"/ʃɑp/","definition":"a place where you buy things","arabic":"متجر / دكان","example":"The shop sells toys.","image_id":"IMG-RW-L02-U2-LS1-V08","audio_id":"AUD-RW-L02-U2-LS1-V08","tier":"core"},{"word":"doctor","pos":"noun","ipa":"/ˈdɑktər/","definition":"a person who helps sick people get well","arabic":"طبيب","example":"The doctor checks my heart.","image_id":"IMG-RW-L02-U2-LS1-V09","audio_id":"AUD-RW-L02-U2-LS1-V09","tier":"core"},{"word":"nurse","pos":"noun","ipa":"/nɝs/","definition":"a person who cares for sick people in a hospital","arabic":"ممرض / ممرضة","example":"The nurse gives me medicine.","image_id":"IMG-RW-L02-U2-LS1-V10","audio_id":"AUD-RW-L02-U2-LS1-V10","tier":"core"},{"word":"police officer","pos":"noun","ipa":"/pəˈlis ˈɔfəsər/","definition":"a person who keeps people safe and follows the law","arabic":"شرطي","example":"The police officer helps us cross.","image_id":"IMG-RW-L02-U2-LS1-V11","audio_id":"AUD-RW-L02-U2-LS1-V11","tier":"core"},{"word":"firefighter","pos":"noun","ipa":"/ˈfaɪərˌfaɪtər/","definition":"a person who puts out fires","arabic":"رجل إطفاء","example":"The firefighter is very brave.","image_id":"IMG-RW-L02-U2-LS1-V12","audio_id":"AUD-RW-L02-U2-LS1-V12","tier":"core"},{"word":"neighbor","pos":"noun","ipa":"/ˈneɪbər/","definition":"a person who lives near you","arabic":"جار","example":"Our neighbor gives us dates.","image_id":"IMG-RW-L02-U2-LS1-V13","audio_id":"AUD-RW-L02-U2-LS1-V13","tier":"core"},{"word":"near","pos":"preposition","ipa":"/nɪr/","definition":"not far","arabic":"قريب من","example":"The park is near my school.","image_id":"IMG-RW-L02-U2-LS1-V14","audio_id":"AUD-RW-L02-U2-LS1-V14","tier":"core"},{"word":"community","pos":"noun","ipa":"/kəˈmjunəti/","definition":"the people who live in one place and help each other","arabic":"مجتمع","example":"Our community is friendly.","image_id":"IMG-RW-L02-U2-LS1-V15","audio_id":"AUD-RW-L02-U2-LS1-V15","tier":"tier2"},{"word":"safe","pos":"adjective","ipa":"/seɪf/","definition":"not in danger","arabic":"آمن","example":"Wear a helmet to be safe.","image_id":"IMG-RW-L02-U2-LS1-V16","audio_id":"AUD-RW-L02-U2-LS1-V16","tier":"tier2"}],"explanation":{"text":"A **compound word** is two small words joined to make one new word: **fire + fighter = firefighter**.\n\nTo find the meaning, **split** the word: *fire* + *fighter* → a person who **fights fire**.\n\nMany compound words name **people**, **places** and **things** in our neighborhood.","examples":["**fire + fighter = firefighter** → a person who fights fires.","**play + ground = playground** → ground (a place) for playing.","**neighbor + hood = neighborhood** → the place where neighbors live.","**book + shop = bookshop** → a shop that sells books.","**class + room = classroom** → a room for a class.","**police + man → policeman**, but we also say **police officer** (two words).","**post + man = postman** → a person who brings letters (mail carrier).","**sun + glasses = sunglasses** → glasses for the sun.","**week + end = weekend** → the end of the week."],"common_errors":["✗ fire fighter / fire-fighter → ✓ firefighter (Write this compound word as one word.)","✗ The hospital is near from my house. → ✓ The hospital is near my house. (No **from** after near.)","✗ I go to the mosque for pray. → ✓ I go to the mosque to pray. (Use **to** + action word.)","✗ He is doctor. → ✓ He is a doctor. (Use **a** before jobs.)","✗ I buy from the bakery a bread. → ✓ I buy bread from the bakery. (No **a** before bread; put *from the bakery* at the end.)","✗ My neighbor is live next to us. → ✓ My neighbor lives next to us. (No **is**; add **-s**.)","✗ The library is a shop to buy books. → ✓ The library lends books; a bookshop sells books. (Library ≠ bookshop!)"],"arabic":"الكلمة المركبة كلمتان صغيرتان تجتمعان لتكوّنا كلمة جديدة: fire + fighter = firefighter.\n\nلمعرفة المعنى قسّم الكلمة: fire (نار) + fighter (مقاتل) ← شخص يكافح النار.\n\nانتبه: library مكتبة نستعير منها الكتب، أما bookshop فمتجر نشتري منه الكتب. ونقول He is a doctor بإضافة a قبل المهنة."},"video":{"script":[{"time":"00:00–00:15","narration":"Welcome to our neighborhood! Let's meet the places and the helpers.","on_screen":"My Neighborhood","visual":"A bird's-eye view of a Saudi neighborhood: houses, mosque, park, market, hospital."},{"time":"00:15–00:55","narration":"Here is the mosque. Here is the market. Here is the park, the library and the bakery.","on_screen":"mosque · market · park · library · bakery","visual":"Each building lights up and grows a little as it is named."},{"time":"00:55–01:30","narration":"Who helps us? The doctor and the nurse at the hospital, the police officer on the street, the firefighter at the fire station.","on_screen":"doctor · nurse · police officer · firefighter","visual":"Helpers wave from their places."},{"time":"01:30–02:05","narration":"Fire… fighter… FIREFIGHTER! Two small words make one big word. That's a compound word!","on_screen":"fire + fighter = firefighter","visual":"Two word blocks slide together and click."},{"time":"02:05–02:30","narration":"Play + ground = playground. Neighbor + hood = neighborhood. Book + shop = bookshop!","on_screen":"Compound words","visual":"More pairs click together."},{"time":"02:30–02:45","narration":"Our community is safe because people help each other. How can YOU help?","on_screen":"community · safe","visual":"Neighbors wave in the street; Saqr flies over."}],"captions_ar":["مرحبًا بكم في حيّنا! لنتعرف على الأماكن والمساعدين.","هذا المسجد، وهذا السوق، وهذه الحديقة والمكتبة والمخبز.","مَن يساعدنا؟ الطبيب والممرضة في المستشفى، والشرطي في الشارع، ورجل الإطفاء في محطة الإطفاء.","fire… fighter… firefighter! كلمتان صغيرتان تكوّنان كلمة كبيرة. هذه كلمة مركبة!","play + ground = playground، neighbor + hood = neighborhood، book + shop = bookshop!","مجتمعنا آمن لأن الناس يساعدون بعضهم. كيف يمكنك أن تساعد؟"],"voice":"Narrator: American English, friendly female teacher, speed 0.85, like a neighborhood tour guide. Adam: curious boy voice."},"texts":[],"activities":[{"id":"RW-L02-U2-LS1-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the correct word.","instructions_ar":"اختر الكلمة الصحيحة.","items":[{"q":"Sick people go to the ___.","answer":"hospital","explanation":"Hospitals help sick people.","explanation_ar":"المستشفى.","options":["bakery","hospital","park","library"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"We borrow books from the ___.","answer":"library","explanation":"A library lends books.","explanation_ar":"المكتبة.","options":["library","market","mosque","bakery"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"A person who puts out fires is a ___.","answer":"firefighter","explanation":"Firefighters fight fires.","explanation_ar":"رجل الإطفاء.","options":["nurse","neighbor","baker","firefighter"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Fresh bread comes from the ___.","answer":"bakery","explanation":"Bakeries make bread.","explanation_ar":"المخبز.","options":["hospital","library","bakery","street"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"The man who lives next door is my ___.","answer":"neighbor","explanation":"A neighbor lives near you.","explanation_ar":"الجار.","options":["doctor","nurse","neighbor","firefighter"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Muslims pray in a ___.","answer":"mosque","explanation":"The mosque is for prayer.","explanation_ar":"المسجد.","options":["mosque","market","shop","park"],"dok":1,"skill":"vocabulary","stage":"controlled"}]},{"id":"RW-L02-U2-LS1-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Compound words: split or join.","instructions_ar":"الكلمات المركبة: قسّم أو اجمع.","items":[{"q":"Which two words make *playground*?","answer":"play + ground","explanation":"play + ground.","explanation_ar":"play + ground.","options":["pla + yground","player + round","play + ground","plays + ground"],"dok":1,"skill":"compound words","stage":"guided"},{"q":"*book + shop* = ___","answer":"bookshop","explanation":"book + shop = bookshop.","explanation_ar":"bookshop.","options":["bookshop","bookshelf","shopbook","bookstop"],"dok":1,"skill":"compound words","stage":"guided"},{"q":"A *firefighter* is a person who ___.","answer":"fights fires","explanation":"fire + fighter.","explanation_ar":"يكافح النار.","options":["makes fires","fights fires","sells fire","draws fires"],"dok":1,"skill":"word meaning","stage":"guided"},{"q":"Which school word is a compound word?","answer":"classroom","explanation":"class + room.","explanation_ar":"classroom.","options":["doctor","market","street","classroom"],"dok":1,"skill":"compound words","stage":"guided"},{"q":"*neighbor + hood* = ___","answer":"neighborhood","explanation":"neighbor + hood.","explanation_ar":"neighborhood.","options":["neighborwood","hoodneighbor","neighbors","neighborhood"],"dok":1,"skill":"compound words","stage":"guided"},{"q":"*Sunglasses* are ___.","answer":"glasses for the sun","explanation":"sun + glasses.","explanation_ar":"نظارة للشمس.","options":["a sunny day","glasses for the sun","glasses of juice","a kind of hat"],"dok":2,"skill":"word meaning","stage":"guided"}]},{"id":"RW-L02-U2-LS1-A3","type":"gap_fill","stage":"freer","instructions":"Freer practice: Use the word bank to complete each sentence.","instructions_ar":"استخدم بنك الكلمات.","items":[{"q":"The ________ is a few minutes from my house. It is very near.","answer":"market","explanation":"A place near your house.","explanation_ar":"السوق قريب.","stage":"freer"},{"q":"A ________ helps the doctor and cares for sick people.","answer":"nurse","explanation":"Nurses care for sick people.","explanation_ar":"الممرضة.","stage":"freer"},{"q":"The ________ officer stops the cars so children can cross.","answer":"police","explanation":"Police officers keep streets safe.","explanation_ar":"الشرطي.","stage":"freer"},{"q":"Our ________ is friendly. Everyone helps each other.","answer":"community","explanation":"Community = people in one place.","explanation_ar":"مجتمعنا.","stage":"freer"},{"q":"Wear a seat belt to stay ________.","answer":"safe","explanation":"Safe = not in danger.","explanation_ar":"آمن.","stage":"freer"},{"q":"We walk on the ________ to the shop.","answer":"street","explanation":"A street is a road in town.","explanation_ar":"الشارع.","stage":"freer"}]},{"id":"RW-L02-U2-LS1-A4","type":"open","stage":"production","instructions":"Writing: Write about YOUR neighborhood.","instructions_ar":"اكتب عن حيّك.","items":[{"q":"What places are near your house? Write two.","answer":"A mosque and a bakery are near my house.","explanation":"Two places.","explanation_ar":"مكانان.","dok":1,"skill":"personal writing","stage":"production"},{"q":"Who is a helper in your neighborhood? Where does he or she work?","answer":"A doctor works at the hospital near my house.","explanation":"Helper + place.","explanation_ar":"مساعد + مكان.","dok":2,"skill":"personal writing","stage":"production"},{"q":"Write one compound word and its two parts.","answer":"football = foot + ball","explanation":"Any compound word.","explanation_ar":"أي كلمة مركبة.","dok":2,"skill":"compound words","stage":"production"},{"q":"Why is your neighborhood safe? Use because.","answer":"It is safe because police officers drive on our street.","explanation":"because + reason.","explanation_ar":"because + سبب.","dok":2,"skill":"reasons","stage":"production"}]}],"game":{"name":"Compound Word Builder","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Word builder: two halves float on the screen; the child drags them together. Correct words lock and show a picture; the child then taps the right meaning from three choices.","Teams take turns.","A player takes one card from each pile.","If they make a real compound word, the player says it and its meaning (\"Play + ground – a place to play!\").","Correct word + meaning = 2 points; word only = 1 point.","Wrong pairs go back under the piles."],"data":[]},"exit_quiz":[{"q":"Where do doctors and nurses work?","answer":"at the hospital","explanation":"Hospitals.","explanation_ar":"في المستشفى.","options":["at the bakery","at the library","at the park","at the hospital"],"dok":1,"skill":"vocabulary"},{"q":"Which is a compound word?","answer":"firefighter","explanation":"fire + fighter.","explanation_ar":"firefighter.","options":["firefighter","nurse","street","market"],"dok":1,"skill":"compound words"},{"q":"*A person who lives near you* is a ___.","answer":"neighbor","explanation":"Neighbor.","explanation_ar":"الجار.","options":["nurse","baker","doctor","neighbor"],"dok":1,"skill":"vocabulary"},{"q":"Which two words make *weekend*?","answer":"week + end","explanation":"week + end.","explanation_ar":"week + end.","options":["wee + kend","week + end","weak + end","we + ekend"],"dok":1,"skill":"compound words"},{"q":"Which sentence about the park is correct?","answer":"The park is near my house.","explanation":"No *from* after near.","explanation_ar":"بدون from.","options":["The park is near from my house.","The park near is my house.","The park is near my house.","The park is near at my house."],"dok":2,"skill":"usage"},{"q":"You want to read a book and give it back later. Where do you go?","answer":"the library","explanation":"Libraries lend books.","explanation_ar":"المكتبة.","options":["the bakery","the library","the hospital","the mosque"],"dok":2,"skill":"vocabulary in context"},{"q":"*Our community is friendly.* *Community* means ___.","answer":"people who live in one place and help each other","explanation":"Community = people in one place.","explanation_ar":"المجتمع.","options":["a big hospital","people who live in one place and help each other","a fire truck","a kind of shop"],"dok":1,"skill":"vocabulary"},{"q":"Which sentence about a job is correct?","answer":"He is a firefighter.","explanation":"Use *a* before jobs.","explanation_ar":"a قبل المهنة.","options":["He is firefighter.","He firefighter is.","He is a fire fighter man.","He is a firefighter."],"dok":2,"skill":"usage"},{"q":"What does *bookshop* mean?","answer":"a shop that sells books","explanation":"book + shop.","explanation_ar":"متجر كتب.","options":["a library","a shelf for books","a shop that sells books","a book about shops"],"dok":2,"skill":"word meaning"},{"q":"Why do we split compound words?","answer":"to find the meaning from the two small words","explanation":"The parts give the meaning.","explanation_ar":"لمعرفة المعنى من الجزأين.","options":["to find the meaning from the two small words","to make them longer","to spell them wrong","to find a rhyme"],"dok":3,"skill":"strategy"}],"images":[{"id":"IMG-RW-L02-U2-LS1-V01","prompt":"Picture for the word 'street': a quiet Saudi street with houses and palm trees"},{"id":"IMG-RW-L02-U2-LS1-V02","prompt":"Picture for the word 'mosque': a neighborhood mosque with a minaret"},{"id":"IMG-RW-L02-U2-LS1-V03","prompt":"Picture for the word 'market': a busy fruit market with stalls"},{"id":"IMG-RW-L02-U2-LS1-V04","prompt":"Picture for the word 'park': a park with grass, trees and swings"},{"id":"IMG-RW-L02-U2-LS1-V05","prompt":"Picture for the word 'hospital': a hospital building with an ambulance"},{"id":"IMG-RW-L02-U2-LS1-V06","prompt":"Picture for the word 'library': shelves of books with a child reading"},{"id":"IMG-RW-L02-U2-LS1-V07","prompt":"Picture for the word 'bakery': a bakery window with fresh bread"},{"id":"IMG-RW-L02-U2-LS1-V08","prompt":"Picture for the word 'shop': a small corner shop"},{"id":"IMG-RW-L02-U2-LS1-V09","prompt":"Picture for the word 'doctor': a doctor with a stethoscope and a child"},{"id":"IMG-RW-L02-U2-LS1-V10","prompt":"Picture for the word 'nurse': a nurse in scrubs helping a patient"},{"id":"IMG-RW-L02-U2-LS1-V11","prompt":"Picture for the word 'police officer': a Saudi police officer at a crossing"},{"id":"IMG-RW-L02-U2-LS1-V12","prompt":"Picture for the word 'firefighter': a firefighter with a hose and helmet"},{"id":"IMG-RW-L02-U2-LS1-V13","prompt":"Picture for the word 'neighbor': a man next door waving over a wall"},{"id":"IMG-RW-L02-U2-LS1-V14","prompt":"Picture for the word 'near': a school and a park side by side with a short arrow"},{"id":"IMG-RW-L02-U2-LS1-V15","prompt":"Picture for the word 'community': many neighbors waving in a street"},{"id":"IMG-RW-L02-U2-LS1-V16","prompt":"Picture for the word 'safe': a child wearing a bike helmet"},{"id":"IMG-RW-L02-U2-LS1-01","prompt":"A neighborhood map with a mosque, park, market, hospital and fire station."},{"id":"IMG-RW-L02-U2-LS1-02","prompt":"Word blocks with icons joining together."},{"id":"IMG-RW-L02-U2-LS1-03","prompt":"Six community helpers in a row."}],"audio":[{"id":"AUD-RW-L02-U2-LS1-V01","script":"street. Our street has many trees."},{"id":"AUD-RW-L02-U2-LS1-V02","script":"mosque. The mosque is near our house."},{"id":"AUD-RW-L02-U2-LS1-V03","script":"market. We buy fruit at the market."},{"id":"AUD-RW-L02-U2-LS1-V04","script":"park. Children play in the park."},{"id":"AUD-RW-L02-U2-LS1-V05","script":"hospital. The hospital is open all night."},{"id":"AUD-RW-L02-U2-LS1-V06","script":"library. I borrow books from the library."},{"id":"AUD-RW-L02-U2-LS1-V07","script":"bakery. The bakery smells good."},{"id":"AUD-RW-L02-U2-LS1-V08","script":"shop. The shop sells toys."},{"id":"AUD-RW-L02-U2-LS1-V09","script":"doctor. The doctor checks my heart."},{"id":"AUD-RW-L02-U2-LS1-V10","script":"nurse. The nurse gives me medicine."},{"id":"AUD-RW-L02-U2-LS1-V11","script":"police officer. The police officer helps us cross."},{"id":"AUD-RW-L02-U2-LS1-V12","script":"firefighter. The firefighter is very brave."},{"id":"AUD-RW-L02-U2-LS1-V13","script":"neighbor. Our neighbor gives us dates."},{"id":"AUD-RW-L02-U2-LS1-V14","script":"near. The park is near my school."},{"id":"AUD-RW-L02-U2-LS1-V15","script":"community. Our community is friendly."},{"id":"AUD-RW-L02-U2-LS1-V16","script":"safe. Wear a helmet to be safe."},{"id":"AUD-RW-L02-U2-LS1-VID","script":"Welcome to our neighborhood! Let's meet the places and the helpers. Here is the mosque. Here is the market. Here is the park, the library and the bakery. Who helps us? The doctor and the nurse at the hospital, the police officer on the street, the firefighter at the fire station. Fire… fighter… FIREFIGHTER! Two small words make one big word. That's a compound word! Play + ground = playground. Neighbor + hood = neighborhood. Book + shop = bookshop! Our community is safe because people help each other. How can YOU help?"}]},{"id":"RW-L02-U2-LS2","title":"Helpers in Our Neighborhood","lesson_type":"close_reading","objectives":["read an information text of about 110 words and match each helper with a place and a job","make text-to-self connections: \"This reminds me of…\"","answer literal and inferential questions with evidence"],"objectives_ar":["قراءة نص معلوماتي من نحو 110 كلمات ومطابقة كل مساعد بمكانه وعمله.","عمل روابط بين النص والنفس: هذا يذكّرني بـ...","الإجابة عن أسئلة حرفية واستنتاجية مع الدليل."],"success_criteria":["I can read about the helpers in a neighborhood.","I can match a helper, a place and a job.","I can say: This reminds me of…"],"success_criteria_ar":["أستطيع القراءة عن المساعدين في الحي.","أستطيع مطابقة المساعد بالمكان والعمل.","أستطيع قول: هذا يذكّرني بـ..."],"map_area":"Informational Text: Key Ideas and Details","vocabulary":[{"word":"sick","pos":"adjective","ipa":"/sɪk/","definition":"not well; ill","arabic":"مريض","example":"I stay home when I am sick.","image_id":"IMG-RW-L02-U2-LS2-V01","audio_id":"AUD-RW-L02-U2-LS2-V01","tier":"core"},{"word":"get better","pos":"verb","ipa":"/ɡɛt ˈbɛtər/","definition":"to become well again","arabic":"يتحسن / يتعافى","example":"Rest and you will get better.","image_id":"IMG-RW-L02-U2-LS2-V02","audio_id":"AUD-RW-L02-U2-LS2-V02","tier":"core"},{"word":"fire truck","pos":"noun","ipa":"/ˈfaɪər trʌk/","definition":"a big truck that carries firefighters and water","arabic":"سيارة إطفاء","example":"The fire truck is red.","image_id":"IMG-RW-L02-U2-LS2-V03","audio_id":"AUD-RW-L02-U2-LS2-V03","tier":"core"},{"word":"cross","pos":"verb","ipa":"/krɔs/","definition":"to go from one side to the other","arabic":"يعبر","example":"Look left and right before you cross.","image_id":"IMG-RW-L02-U2-LS2-V04","audio_id":"AUD-RW-L02-U2-LS2-V04","tier":"core"},{"word":"librarian","pos":"noun","ipa":"/laɪˈbrɛriən/","definition":"a person who works in a library","arabic":"أمين المكتبة","example":"The librarian finds a book for me.","image_id":"IMG-RW-L02-U2-LS2-V05","audio_id":"AUD-RW-L02-U2-LS2-V05","tier":"core"},{"word":"baker","pos":"noun","ipa":"/ˈbeɪkər/","definition":"a person who makes bread and cakes","arabic":"خباز","example":"The baker makes fresh bread.","image_id":"IMG-RW-L02-U2-LS2-V06","audio_id":"AUD-RW-L02-U2-LS2-V06","tier":"core"},{"word":"lead","pos":"verb","ipa":"/lid/","definition":"to go first and show others what to do","arabic":"يقود / يؤمّ","example":"The imam leads the prayer.","image_id":"IMG-RW-L02-U2-LS2-V07","audio_id":"AUD-RW-L02-U2-LS2-V07","tier":"core"}],"explanation":{"text":"Good readers **connect** what they read to their own life. This is a **text-to-self connection**.\n\nUse these sentence starters: **This reminds me of…** / **I know about this because…** / **This is like…**\n\nConnections help you **understand** and **remember** the text. A good connection matches an idea in the text.","examples":["Text: *Doctors and nurses help sick people get better.* → **This reminds me of** the time a nurse helped me at the clinic.","Text: *The baker gets up very early.* → **I know about this because** my uncle buys bread at 6 a.m. and it is hot.","Text: *Police officers help people cross the road.* → **This is like** the officer near my school.","Text: *The librarian helps us find good books.* → **This reminds me of** Ms. Huda in our school library.","Text: *The imam leads the prayers.* → **I know about this because** I pray at the mosque with my father.","Text: *Firefighters drive a big red fire truck.* → **This reminds me of** a fire truck I saw on the street.","Weak connection: *I like pizza.* → It does not match the text.","Strong connection: *Our neighbor is a doctor. She helps sick children, like the doctors in the text.*","Question: *How can YOU help?* → I can help my neighbor carry bags."],"common_errors":["✗ This remind me of my school. → ✓ This reminds me of my school. (*This* → **reminds**.)","✗ The doctors helps sick people. → ✓ The doctors help sick people. (Many doctors → **help**.)","✗ Firefighters put the fire out of. → ✓ Firefighters put out fires. (Say **put out** fires.)","✗ The baker wake up early. → ✓ The baker gets up early. (One baker → **gets** / **wakes**.)","✗ They help people to cross the street road. → ✓ They help people cross the road. (Say **cross the road**.)","✗ My connection: I have a cat. → ✓ My connection: My uncle is a police officer, like in the text. (Connections must match the text.)"],"arabic":"القارئ الجيد يربط ما يقرؤه بحياته؛ وهذا يسمى الربط بين النص والنفس.\n\nاستخدم: This reminds me of… (هذا يذكّرني بـ...) / I know about this because… / This is like…\n\nالروابط تساعدك على الفهم والتذكر، والرابط الجيد يتصل بفكرة في النص.\n\nانتبه: نقول This reminds me بإضافة s، ونقول The doctors help بدون s مع الجمع."},"video":{"script":[{"time":"00:00–00:20","narration":"Who helps us in our neighborhood? Let's read and connect!","on_screen":"Helpers in Our Neighborhood","visual":"A tour bus with Saqr as driver drives into a neighborhood."},{"time":"00:20–01:25","narration":"A neighborhood is the place where we live… At the Hospital – Doctors and nurses…","on_screen":"(text, section by section)","visual":"Each heading appears as a road sign; the bus stops at each place and the helper waves."},{"time":"01:25–01:55","narration":"Adam reads about the nurse. He says, 'This reminds me of the nurse who helped me when I was sick!'","on_screen":"This reminds me of…","visual":"A memory bubble shows Adam in a clinic with a kind nurse."},{"time":"01:55–02:25","narration":"A good connection matches the text. 'I like pizza' – no connection! 'My neighbor is a doctor' – a great connection!","on_screen":"Strong ✔ / Weak ✗","visual":"Two bubbles: one with pizza fades out; one with a doctor neighbor glows."},{"time":"02:25–02:55","narration":"Read, connect, remember. Now – how can YOU help?","on_screen":"How can YOU help?","visual":"Children help neighbors: carrying bags, watering plants, picking up litter."}],"captions_ar":["مَن يساعدنا في حيّنا؟ لنقرأ ونربط!","الحي هو المكان الذي نسكن فيه… في المستشفى: الأطباء والممرضون…","يقرأ آدم عن الممرضة ويقول: هذا يذكّرني بالممرضة التي ساعدتني عندما كنت مريضًا!","الرابط الجيد يتصل بالنص. \"أحب البيتزا\" ليس رابطًا! \"جارتي طبيبة\" رابط رائع!","اقرأ واربط وتذكّر. والآن: كيف يمكنك أن تساعد؟"],"voice":"Narrator: American English, warm female teacher, speed 0.85. Adam: curious boy making connections. Gentle street sounds."},"texts":[{"type":"reading","title":"Helpers in Our Neighborhood","body":"A neighborhood is the place where we live. Many people work there to help us.\n\n**At the Hospital** – Doctors and nurses work at the hospital. They help sick people get better.\n\n**At the Fire Station** – Firefighters put out fires. They drive a big red fire truck. They are brave!\n\n**On the Street** – Police officers keep our streets safe. They help people cross the road.\n\n**At the Library and the Bakery** – The librarian helps us find good books. The baker gets up very early and makes fresh bread for everyone.\n\n**At the Mosque** – The imam leads the prayers and teaches people.\n\nThese helpers make our neighborhood a better place. How can YOU help?","word_count":112,"audio_id":"AUD-RW-L02-U2-LS2-T1","id":"TXT-RW-L02-U2-LS2-1","genre":"informational","role":"main","difficulty":"200L–350L","glossary":[{"word":"put out","definition":"stop a fire","arabic":"يطفئ"},{"word":"imam","definition":"the man who leads prayers at the mosque","arabic":"الإمام"},{"word":"librarian","definition":"a person who works in a library","arabic":"أمين المكتبة"}]}],"activities":[{"id":"RW-L02-U2-LS2-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read the text. Choose the answer.","instructions_ar":"اقرأ النص واختر الإجابة.","items":[{"q":"Who works at the hospital?","answer":"doctors and nurses","explanation":"Text: Doctors and nurses work at the hospital.","explanation_ar":"الأطباء والممرضون.","options":["doctors and nurses","firefighters","bakers","police officers"],"dok":1,"skill":"key details: who","stage":"controlled"},{"q":"What do firefighters drive?","answer":"a big red fire truck","explanation":"Text: a big red fire truck.","explanation_ar":"سيارة إطفاء حمراء.","options":["a white bus","a police car","a bicycle","a big red fire truck"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Who helps people cross the road?","answer":"police officers","explanation":"Text: They help people cross the road.","explanation_ar":"الشرطة.","options":["police officers","nurses","librarians","bakers"],"dok":1,"skill":"key details: who","stage":"controlled"},{"q":"When does the baker get up?","answer":"very early","explanation":"Text: very early.","explanation_ar":"مبكرًا جدًا.","options":["very late","at night","very early","at lunch"],"dok":1,"skill":"key details: when","stage":"controlled"},{"q":"Who leads the prayers?","answer":"the imam","explanation":"Text: The imam leads the prayers.","explanation_ar":"الإمام.","options":["the librarian","the imam","the doctor","the baker"],"dok":1,"skill":"key details: who","stage":"controlled"},{"q":"What does the librarian help us find?","answer":"good books","explanation":"Text: helps us find good books.","explanation_ar":"كتبًا جيدة.","options":["fresh bread","a doctor","good books","the fire station"],"dok":1,"skill":"key details","stage":"controlled"}]},{"id":"RW-L02-U2-LS2-A2","type":"true_false","stage":"guided","instructions":"Guided practice: True or false?","instructions_ar":"صح أم خطأ؟","items":[{"q":"A neighborhood is the place where we live.","answer":"true","explanation":"First sentence.","explanation_ar":"الجملة الأولى.","options":["true","false"],"dok":1,"skill":"key details","stage":"guided"},{"q":"Firefighters make fresh bread.","answer":"false","explanation":"Bakers make bread.","explanation_ar":"الخباز يصنع الخبز.","options":["true","false"],"dok":1,"skill":"key details","stage":"guided"},{"q":"Police officers keep our streets safe.","answer":"true","explanation":"Text says so.","explanation_ar":"صحيح.","options":["true","false"],"dok":1,"skill":"key details","stage":"guided"},{"q":"Nurses work at the library.","answer":"false","explanation":"Nurses work at the hospital.","explanation_ar":"يعمل الممرضون في المستشفى.","options":["true","false"],"dok":1,"skill":"key details","stage":"guided"},{"q":"The baker makes bread for everyone.","answer":"true","explanation":"Text: for everyone.","explanation_ar":"صحيح.","options":["true","false"],"dok":1,"skill":"key details","stage":"guided"},{"q":"The text ends with a question for the reader.","answer":"true","explanation":"How can YOU help?","explanation_ar":"صحيح.","options":["true","false"],"dok":2,"skill":"text structure","stage":"guided"}]},{"id":"RW-L02-U2-LS2-A3","type":"highlight","stage":"freer","instructions":"Find the evidence: Underline the evidence or choose the best answer.","instructions_ar":"ضع خطًا تحت الدليل أو اختر.","items":[{"q":"Underline the sentence that shows firefighters are not afraid.","answer":"They are brave!","explanation":"Brave = not afraid.","explanation_ar":"شجعان.","evidence":"They are brave!","text_id":"TXT-RW-L02-U2-LS2-1","dok":2,"skill":"evidence","stage":"freer","sentences":["A neighborhood is the place where we live.","Many people work there to help us.","**At the Hospital** – Doctors and nurses work at the hospital.","They help sick people get better.","**At the Fire Station** – Firefighters put out fires.","They drive a big red fire truck.","They are brave!","**On the Street** – Police officers keep our streets safe.","They help people cross the road.","**At the Library and the Bakery** – The librarian helps us find good books.","The baker gets up very early and makes fresh bread for everyone.","**At the Mosque** – The imam leads the prayers and teaches people.","These helpers make our neighborhood a better place.","How can YOU help?"]},{"q":"Underline what doctors and nurses do.","answer":"They help sick people get better.","explanation":"This is their job.","explanation_ar":"هذا عملهم.","evidence":"They help sick people get better.","text_id":"TXT-RW-L02-U2-LS2-1","dok":1,"skill":"evidence","stage":"freer","sentences":["A neighborhood is the place where we live.","Many people work there to help us.","**At the Hospital** – Doctors and nurses work at the hospital.","They help sick people get better.","**At the Fire Station** – Firefighters put out fires.","They drive a big red fire truck.","They are brave!","**On the Street** – Police officers keep our streets safe.","They help people cross the road.","**At the Library and the Bakery** – The librarian helps us find good books.","The baker gets up very early and makes fresh bread for everyone.","**At the Mosque** – The imam leads the prayers and teaches people.","These helpers make our neighborhood a better place.","How can YOU help?"]},{"q":"Why does the baker get up very early?","answer":"to make fresh bread before people need it","explanation":"Fresh bread must be ready in the morning.","explanation_ar":"ليجهز الخبز الطازج.","options":["to go to school","to help people cross the road","to put out fires","to make fresh bread before people need it"],"dok":2,"skill":"inference","stage":"freer"},{"q":"Which is a STRONG text-to-self connection?","answer":"My aunt is a nurse. She helps sick people, like in the text.","explanation":"It matches the text.","explanation_ar":"يتصل بالنص.","options":["My aunt is a nurse. She helps sick people, like in the text.","I like football.","My bag is blue.","I have two cats."],"dok":2,"skill":"connections","stage":"freer"}]},{"id":"RW-L02-U2-LS2-A4","type":"open","stage":"production","instructions":"Writing: Make connections.","instructions_ar":"اعمل روابط.","items":[{"q":"Write a connection: This reminds me of…","answer":"This reminds me of the police officer near my school.","explanation":"A connection to the text.","explanation_ar":"رابط بالنص.","dok":2,"skill":"connections","stage":"production"},{"q":"Write a connection with: I know about this because…","answer":"I know about this because I go to the bakery with my dad.","explanation":"A connection with a reason.","explanation_ar":"رابط مع سبب.","dok":2,"skill":"connections","stage":"production"},{"q":"Which helper do you want to be? Why?","answer":"I want to be a doctor because I want to help sick people.","explanation":"Job + because.","explanation_ar":"مهنة + because.","dok":3,"skill":"evaluate","stage":"production"},{"q":"How can YOU help your neighborhood?","answer":"I can pick up trash in the park.","explanation":"A helpful action.","explanation_ar":"تصرف مفيد.","dok":2,"skill":"connect","stage":"production"}]},{"id":"RW-L02-U2-LS2-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"Helpers in Our Neighborhood\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “Helpers in Our Neighborhood”.","answer":"112 words","title":"Helpers in Our Neighborhood","body":"A neighborhood is the place where we live. Many people work there to help us.\n\n**At the Hospital** – Doctors and nurses work at the hospital. They help sick people get better.\n\n**At the Fire Station** – Firefighters put out fires. They drive a big red fire truck. They are brave!\n\n**On the Street** – Police officers keep our streets safe. They help people cross the road.\n\n**At the Library and the Bakery** – The librarian helps us find good books. The baker gets up very early and makes fresh bread for everyone.\n\n**At the Mosque** – The imam leads the prayers and teaches people.\n\nThese helpers make our neighborhood a better place. How can YOU help?","words":112,"limit":137}],"time_limit_sec":137}],"game":{"name":"Helper Riddles","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Riddle reveal: three clues appear one by one; the child taps the helper and then the place. Points: 3 after one clue, 2 after two, 1 after three.","The teacher reads clue 1.","Teams may ring and guess the helper and the place.","Correct after clue 1 = 3 points; clue 2 = 2; clue 3 = 1.","A wrong guess = that team waits until the next riddle.","Play 6 riddles."],"data":[]},"exit_quiz":[{"q":"What is *Helpers in Our Neighborhood* mostly about?","answer":"helpers in a neighborhood","explanation":"Every part is about helpers.","explanation_ar":"المساعدون في الحي.","options":["how to bake bread","helpers in a neighborhood","a red kite","a girl's first day"],"dok":1,"skill":"main topic"},{"q":"Where do firefighters work?","answer":"at the fire station","explanation":"Heading: At the Fire Station.","explanation_ar":"محطة الإطفاء.","options":["at the fire station","at the bakery","at the library","at the mosque"],"dok":1,"skill":"key details"},{"q":"Who helps sick people get better?","answer":"doctors and nurses","explanation":"Text: They help sick people get better.","explanation_ar":"الأطباء والممرضون.","options":["bakers","librarians","firefighters","doctors and nurses"],"dok":1,"skill":"key details"},{"q":"Which heading tells you about the imam?","answer":"At the Mosque","explanation":"The imam is in the mosque part.","explanation_ar":"At the Mosque.","options":["On the Street","At the Hospital","At the Mosque","At the Fire Station"],"dok":1,"skill":"text features"},{"q":"*They help people cross the road.* *Cross* means ___.","answer":"go from one side to the other","explanation":"Cross = go to the other side.","explanation_ar":"يعبر.","options":["go from one side to the other","be angry","stop","draw a line"],"dok":2,"skill":"word in context"},{"q":"Which sentence starter makes a text-to-self connection?","answer":"This reminds me of…","explanation":"It connects to your life.","explanation_ar":"يربط بحياتك.","options":["The end.","Once upon a time…","This reminds me of…","First, open your bag."],"dok":1,"skill":"connections"},{"q":"Which connection matches the text best?","answer":"I saw a fire truck help put out a fire.","explanation":"It is about a helper in the text.","explanation_ar":"يتصل بالنص.","options":["I like ice cream.","I saw a fire truck help put out a fire.","My shoes are new.","I can swim."],"dok":2,"skill":"connections"},{"q":"Why does the writer say firefighters are brave?","answer":"They go near dangerous fires to help.","explanation":"Fires are dangerous.","explanation_ar":"النار خطرة.","options":["They make bread.","They read books.","They sleep early.","They go near dangerous fires to help."],"dok":2,"skill":"inference"},{"q":"What is the writer's message at the end?","answer":"Helpers make the neighborhood better, and we can help too.","explanation":"Last two sentences.","explanation_ar":"المساعدون يحسّنون الحي ونحن نستطيع المساعدة.","options":["Only doctors are important.","Helpers make the neighborhood better, and we can help too.","Neighborhoods are boring.","Do not go to the library."],"dok":3,"skill":"author's message"},{"q":"Which helper might you need if your cat is stuck on a high wall?","answer":"a firefighter","explanation":"Firefighters have ladders and rescue.","explanation_ar":"رجل الإطفاء.","options":["a baker","a librarian","a firefighter","an imam"],"dok":3,"skill":"apply"}],"images":[{"id":"IMG-RW-L02-U2-LS2-V01","prompt":"Picture for the word 'sick': a child in bed with a thermometer"},{"id":"IMG-RW-L02-U2-LS2-V02","prompt":"Picture for the word 'get better': a smiling child getting out of bed"},{"id":"IMG-RW-L02-U2-LS2-V03","prompt":"Picture for the word 'fire truck': a red fire truck with a ladder"},{"id":"IMG-RW-L02-U2-LS2-V04","prompt":"Picture for the word 'cross': children crossing at a zebra crossing"},{"id":"IMG-RW-L02-U2-LS2-V05","prompt":"Picture for the word 'librarian': Ms. Huda handing a book to a child"},{"id":"IMG-RW-L02-U2-LS2-V06","prompt":"Picture for the word 'baker': a baker taking bread out of an oven"},{"id":"IMG-RW-L02-U2-LS2-V07","prompt":"Picture for the word 'lead': a guide walking in front of a group"},{"id":"IMG-RW-L02-U2-LS2-01","prompt":"Doctors and nurses at a hospital next to a fire station."},{"id":"IMG-RW-L02-U2-LS2-02","prompt":"A police officer, a librarian, a baker and a mosque."},{"id":"IMG-RW-L02-U2-LS2-03","prompt":"Adam reads and remembers a nurse who helped him."}],"audio":[{"id":"AUD-RW-L02-U2-LS2-V01","script":"sick. I stay home when I am sick."},{"id":"AUD-RW-L02-U2-LS2-V02","script":"get better. Rest and you will get better."},{"id":"AUD-RW-L02-U2-LS2-V03","script":"fire truck. The fire truck is red."},{"id":"AUD-RW-L02-U2-LS2-V04","script":"cross. Look left and right before you cross."},{"id":"AUD-RW-L02-U2-LS2-V05","script":"librarian. The librarian finds a book for me."},{"id":"AUD-RW-L02-U2-LS2-V06","script":"baker. The baker makes fresh bread."},{"id":"AUD-RW-L02-U2-LS2-V07","script":"lead. The imam leads the prayer."},{"id":"AUD-RW-L02-U2-LS2-T1","script":"A neighborhood is the place where we live. Many people work there to help us. **At the Hospital** – Doctors and nurses work at the hospital. They help sick people get better. **At the Fire Station** – Firefighters put out fires. They drive a big red fire truck. They are brave! **On the Street** – Police officers keep our streets safe. They help people cross the road. **At the Library and the Bakery** – The librarian helps us find good books. The baker gets up very early and makes fresh bread for everyone. **At the Mosque** – The imam leads the prayers and teaches people. These helpers make our neighborhood a better place. How can YOU help?"},{"id":"AUD-RW-L02-U2-LS2-VID","script":"Who helps us in our neighborhood? Let's read and connect! A neighborhood is the place where we live… At the Hospital – Doctors and nurses… Adam reads about the nurse. He says, 'This reminds me of the nurse who helped me when I was sick!' A good connection matches the text. 'I like pizza' – no connection! 'My neighbor is a doctor' – a great connection! Read, connect, remember. Now – how can YOU help?"}]},{"id":"RW-L02-U2-LS3","title":"Main topic and key details: \"A Letter to the Firefighters\"","lesson_type":"strategy_paired_text","objectives":["find the main topic of a text and key details that tell about it","use the title, the first sentence and repeated words as clues","compare the main topics of an information text and a thank-you letter"],"objectives_ar":["تحديد الموضوع الرئيسي للنص والتفاصيل المهمة عنه.","استخدام العنوان والجملة الأولى والكلمات المتكررة أدلةً.","مقارنة الموضوع الرئيسي لنص معلوماتي ورسالة شكر."],"success_criteria":["I can say the main topic of the letter.","I can find three key details.","I can tell a key detail from a small, extra detail."],"success_criteria_ar":["أستطيع قول الموضوع الرئيسي للرسالة.","أستطيع إيجاد ثلاثة تفاصيل مهمة.","أستطيع التمييز بين التفصيل المهم والتفصيل الإضافي الصغير."],"map_area":"Informational Text: Key Ideas and Details","vocabulary":[{"word":"fire","pos":"noun","ipa":"/faɪər/","definition":"hot burning flames","arabic":"نار / حريق","example":"The fire is very hot.","image_id":"IMG-RW-L02-U2-LS3-V01","audio_id":"AUD-RW-L02-U2-LS3-V01","tier":"core"},{"word":"station","pos":"noun","ipa":"/ˈsteɪʃən/","definition":"a building where a service works (fire station, police station)","arabic":"محطة / مركز","example":"The fire station is on our street.","image_id":"IMG-RW-L02-U2-LS3-V02","audio_id":"AUD-RW-L02-U2-LS3-V02","tier":"core"},{"word":"next to","pos":"preposition","ipa":"/nɛkst tu/","definition":"very close; at the side of","arabic":"بجانب","example":"The bakery is next to the mosque.","image_id":"IMG-RW-L02-U2-LS3-V03","audio_id":"AUD-RW-L02-U2-LS3-V03","tier":"core"},{"word":"hard work","pos":"noun","ipa":"/hɑrd wɝk/","definition":"work that needs a lot of effort","arabic":"العمل الجاد","example":"Thank you for your hard work.","image_id":"IMG-RW-L02-U2-LS3-V04","audio_id":"AUD-RW-L02-U2-LS3-V04","tier":"core"},{"word":"grow up","pos":"verb","ipa":"/ɡroʊ ʌp/","definition":"to become an adult","arabic":"يكبر (يصبح بالغًا)","example":"When I grow up, I want to be a pilot.","image_id":"IMG-RW-L02-U2-LS3-V05","audio_id":"AUD-RW-L02-U2-LS3-V05","tier":"core"},{"word":"key detail","pos":"noun","ipa":"/ki ˈditeɪl/","definition":"an important fact that tells about the main topic","arabic":"تفصيل مهم","example":"Find three key details.","image_id":"IMG-RW-L02-U2-LS3-V06","audio_id":"AUD-RW-L02-U2-LS3-V06","tier":"core"},{"word":"again","pos":"adverb","ipa":"/əˈɡɛn/","definition":"one more time","arabic":"مرة أخرى","example":"Thank you again!","image_id":"IMG-RW-L02-U2-LS3-V07","audio_id":"AUD-RW-L02-U2-LS3-V07","tier":"core"}],"explanation":{"text":"The **main topic** is what the whole text is about. **Key details** are important facts that tell more about the main topic.\n\nFind the main topic with clues: the **title**, the **first sentence**, and the words you see **many times**.\n\nNot every detail is a key detail. Ask: **Does this detail help me understand the main topic?**\n\nUse the **Main Topic House**: the main topic goes on the **roof**; key details go in the **rooms**.","examples":["Letter title: *A Letter to the Firefighters* → main topic: **Adam thanks the firefighters**.","First sentence: *Thank you for your hard work!* → a thank-you letter.","Repeated words: **you / thank you / fire**.","Key detail: There was a small fire in the house next to ours.","Key detail: The firefighters came very fast and put out the fire.","Key detail: Everyone was safe.","Small detail: the truck is **red** → true, but not very important.","Information text main topic: **helpers in our neighborhood**.","Information text key details: doctors and nurses help sick people; firefighters put out fires; police officers keep streets safe."],"common_errors":["✗ The main topic is the red truck. → ✓ The main topic is Adam thanking the firefighters. (A small detail is not the main topic.)","✗ Main topic: Adam wants to be a firefighter and the truck is red and… → ✓ Main topic: Adam thanks the firefighters. (Say the main topic in a few words.)","✗ The firefighters come very fast. (for last week) → ✓ The firefighters came very fast. (The letter uses *came* for last week.)","✗ I want help people. → ✓ I want to help people. (Use **want to** + action word.)","✗ When I will grow up… → ✓ When I grow up… (After *when*, use **grow up** (no *will*).)","✗ next of our house → ✓ next to our house (Say **next to**.)"],"arabic":"الموضوع الرئيسي هو ما يتحدث عنه النص كله، والتفاصيل المهمة حقائق تخبرنا بالمزيد عنه.\n\nابحث عن الموضوع بالأدلة: العنوان، والجملة الأولى، والكلمات المتكررة.\n\nليس كل تفصيل مهمًا؛ اسأل: هل يساعدني هذا التفصيل على فهم الموضوع الرئيسي؟\n\nاستخدم بيت الموضوع الرئيسي: الموضوع على السقف، والتفاصيل المهمة في الغرف."},"video":{"script":[{"time":"00:00–00:15","narration":"Adam writes a letter. What is it ALL about?","on_screen":"Main topic + key details","visual":"Adam types at a computer, then prints and signs a letter."},{"time":"00:15–01:00","narration":"Dear Firefighters, Thank you for your hard work! Last week, there was a small fire…","on_screen":"(the letter)","visual":"A small kitchen fire next door; the fire truck arrives; firefighters put it out; neighbors are safe."},{"time":"01:00–01:30","narration":"Clues: the title, the first sentence, the words we see many times – thank you! The main topic: Adam thanks the firefighters.","on_screen":"Main topic: thanking the firefighters","visual":"A house appears; the main topic slides onto the roof."},{"time":"01:30–02:05","narration":"Key details go in the rooms: a small fire, they came fast, everyone was safe.","on_screen":"Key details 🔑","visual":"Three rooms light up with details."},{"time":"02:05–02:40","narration":"The red truck? True, but it is a small detail. Does it help us understand the main topic? Not much!","on_screen":"Small detail ≠ key detail","visual":"A small 'red truck' card sits outside the house."}],"captions_ar":["يكتب آدم رسالة. عمّ تتحدث كلها؟","أعزائي رجال الإطفاء، شكرًا لعملكم الجاد! في الأسبوع الماضي شبّ حريق صغير…","الأدلة: العنوان، والجملة الأولى، والكلمات المتكررة مثل thank you. الموضوع الرئيسي: آدم يشكر رجال الإطفاء.","التفاصيل المهمة في الغرف: حريق صغير، جاؤوا بسرعة، الجميع بأمان.","الشاحنة الحمراء؟ صحيح، لكنه تفصيل صغير لا يساعدنا كثيرًا على فهم الموضوع."],"voice":"Narrator: American English, warm female teacher, speed 0.85. Adam reads his letter in a sincere, grateful boy voice."},"texts":[{"type":"reading","title":"A Letter to the Firefighters","body":"Dear Firefighters,\n\nThank you for your hard work! Last week, there was a small fire in the kitchen of the house next to ours. You came very fast in your red truck. You put out the fire, and everyone was safe.\n\nYou are brave and kind. When I grow up, I want to help people like you.\n\nCan I visit the fire station one day? Thank you again!\n\nYour friend,\n\nAdam Rahman","word_count":72,"audio_id":"AUD-RW-L02-U2-LS3-T1","id":"TXT-RW-L02-U2-LS3-1","genre":"letter/email","role":"paired","difficulty":"200L–350L","glossary":[{"word":"last week","definition":"the week before this one","arabic":"الأسبوع الماضي"},{"word":"next to ours","definition":"next to our house","arabic":"بجانب بيتنا"}]}],"activities":[{"id":"RW-L02-U2-LS3-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read the letter. Choose the answer.","instructions_ar":"اقرأ الرسالة واختر الإجابة.","items":[{"q":"Who wrote the letter?","answer":"Adam Rahman","explanation":"The name at the end.","explanation_ar":"آدم رحمن.","options":["Omar Haddad","Adam Rahman","Mr. Khalid","a firefighter"],"dok":1,"skill":"key details","text_id":"TXT-RW-L02-U2-LS3-1","stage":"controlled"},{"q":"Who is the letter for?","answer":"the firefighters","explanation":"Dear Firefighters,","explanation_ar":"لرجال الإطفاء.","options":["the firefighters","the doctors","Adam's teacher","the baker"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Where was the fire?","answer":"in the kitchen of the house next door","explanation":"Text: in the kitchen of the house next to ours.","explanation_ar":"في مطبخ البيت المجاور.","options":["at Adam's school","in the park","at the bakery","in the kitchen of the house next door"],"dok":1,"skill":"key details: where","stage":"controlled"},{"q":"How fast did the firefighters come?","answer":"very fast","explanation":"Text: You came very fast.","explanation_ar":"بسرعة كبيرة.","options":["very fast","very slowly","the next day","after a week"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What does Adam want to do when he grows up?","answer":"help people like the firefighters","explanation":"Text: I want to help people like you.","explanation_ar":"مساعدة الناس.","options":["be a baker","drive a bus","help people like the firefighters","stay at home"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What does Adam ask at the end?","answer":"Can I visit the fire station one day?","explanation":"His question.","explanation_ar":"هل يمكنني زيارة المحطة؟","options":["Can I have a red truck?","Can I visit the fire station one day?","Where is the fire?","Who is the baker?"],"dok":1,"skill":"key details","stage":"controlled"}]},{"id":"RW-L02-U2-LS3-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Main topic or detail? Choose.","instructions_ar":"موضوع رئيسي أم تفصيل؟ اختر.","items":[{"q":"What is the main topic of the letter?","answer":"Adam thanks the firefighters for their help.","explanation":"The whole letter says thank you.","explanation_ar":"آدم يشكر رجال الإطفاء.","options":["The truck is red.","Adam has a computer.","Adam thanks the firefighters for their help.","The fire was in a kitchen."],"dok":1,"skill":"main topic","stage":"guided"},{"q":"Which is a KEY detail?","answer":"Everyone was safe.","explanation":"Being safe is important to the topic.","explanation_ar":"الجميع بأمان.","options":["Everyone was safe.","The truck is red.","Adam's last name is Rahman.","The letter ends with a name."],"dok":2,"skill":"key details","stage":"guided"},{"q":"Which is a SMALL detail?","answer":"The truck is red.","explanation":"The color is not very important.","explanation_ar":"لون الشاحنة تفصيل صغير.","options":["The firefighters put out the fire.","There was a fire next door.","Adam says thank you.","The truck is red."],"dok":2,"skill":"detail vs. key detail","stage":"guided"},{"q":"Which clue tells the main topic fastest?","answer":"the title","explanation":"The title is the first clue.","explanation_ar":"العنوان.","options":["the closing","the title","the name","the question"],"dok":1,"skill":"strategy","stage":"guided"},{"q":"What words do you see many times in the letter?","answer":"you / thank you","explanation":"Repeated words show the topic.","explanation_ar":"you / thank you.","options":["kitchen / bread","school / book","park / kite","you / thank you"],"dok":1,"skill":"strategy","stage":"guided"},{"q":"How are the main topics of the letter and *Helpers in Our Neighborhood* the same?","answer":"Both are about people who help us.","explanation":"Both are about helpers.","explanation_ar":"كلاهما عن المساعدين.","options":["Both are about kites.","Both are about bread.","Both are about people who help us.","Both are poems."],"dok":2,"skill":"compare","stage":"guided"}]},{"id":"RW-L02-U2-LS3-A3","type":"organizer","stage":"freer","instructions":"Organizer: Complete the Main Topic House for the letter.","instructions_ar":"أكمل بيت الموضوع الرئيسي للرسالة.","items":[{"q":"Roof – main topic:","answer":"Adam thanks the firefighters.","explanation":"A short main topic.","explanation_ar":"موضوع قصير.","dok":2,"skill":"main topic","stage":"freer"},{"q":"Room 1 – key detail:","answer":"There was a small fire next door.","explanation":"A key detail.","explanation_ar":"تفصيل مهم.","dok":1,"skill":"key details","stage":"freer"},{"q":"Room 2 – key detail:","answer":"The firefighters came fast and put out the fire.","explanation":"A key detail.","explanation_ar":"تفصيل مهم.","dok":1,"skill":"key details","stage":"freer"},{"q":"Room 3 – key detail:","answer":"Everyone was safe.","explanation":"A key detail.","explanation_ar":"تفصيل مهم.","dok":1,"skill":"key details","stage":"freer"}]},{"id":"RW-L02-U2-LS3-A4","type":"open","stage":"production","instructions":"Writing: Write about main topics.","instructions_ar":"اكتب عن المواضيع الرئيسية.","items":[{"q":"Write the main topic of *Helpers in Our Neighborhood*.","answer":"helpers in our neighborhood","explanation":"A short topic.","explanation_ar":"موضوع قصير.","dok":1,"skill":"main topic","stage":"production"},{"q":"Write two key details from *Helpers in Our Neighborhood*.","answer":"Doctors help sick people. Firefighters put out fires.","explanation":"Two key details.","explanation_ar":"تفصيلان مهمان.","dok":2,"skill":"key details","stage":"production"},{"q":"Write one small detail from the letter. Why is it small?","answer":"The truck is red. It does not help us understand the thank-you.","explanation":"Detail + reason.","explanation_ar":"تفصيل + سبب.","dok":3,"skill":"detail vs. key detail","stage":"production"},{"q":"Who would YOU thank in your neighborhood? Why?","answer":"I would thank the baker because he makes fresh bread every day.","explanation":"Helper + because.","explanation_ar":"مساعد + because.","dok":2,"skill":"connect","stage":"production"}]},{"id":"RW-L02-U2-LS3-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"A Letter to the Firefighters\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “A Letter to the Firefighters”.","answer":"72 words","title":"A Letter to the Firefighters","body":"Dear Firefighters,\n\nThank you for your hard work! Last week, there was a small fire in the kitchen of the house next to ours. You came very fast in your red truck. You put out the fire, and everyone was safe.\n\nYou are brave and kind. When I grow up, I want to help people like you.\n\nCan I visit the fire station one day? Thank you again!\n\nYour friend,\n\nAdam Rahman","words":72,"limit":93}],"time_limit_sec":93},{"id":"RW-L02-U2-LS3-ORG","type":"organizer","organizer":"Main Topic House","instructions":"Organizer: Write the main topic on the roof. Write three key details in the rooms.","items":[{"q":"Roof: main topic","answer":"Adam thanks the firefighters."},{"q":"Room 1: key detail","answer":"There was a small fire next door."},{"q":"Room 2: key detail","answer":"The firefighters came fast and put it out."},{"q":"Room 3: key detail","answer":"Everyone was safe."}]}],"game":{"name":"Build the House","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: House builder: cards drop from the sky; the child drags the main topic to the roof, key details to rooms and small details to the garden. A complete correct house lights up its windows.","Each team gets a house outline and six mixed cards.","In 3 minutes, they place the cards: roof, rooms or outside.","The team reads its house aloud.","Correct roof = 2 points; each correct room = 1 point; each small detail outside = 1 point.","Swap card sets and play again."],"data":[]},"exit_quiz":[{"q":"Key details tell ___.","answer":"more about the main topic","explanation":"They support the topic.","explanation_ar":"تدعم الموضوع.","options":["the page number","the writer's address","the last word","more about the main topic"],"dok":1,"skill":"strategy"},{"q":"What kind of text is *A Letter to the Firefighters*?","answer":"a thank-you letter","explanation":"It says thank you to the firefighters.","explanation_ar":"رسالة شكر.","options":["a thank-you letter","a poem","a play","a menu"],"dok":1,"skill":"genre"},{"q":"Which detail does NOT help much with the main topic?","answer":"The truck is red.","explanation":"The color is a small detail.","explanation_ar":"اللون تفصيل صغير.","options":["The truck is red.","There was a fire.","Everyone was safe.","They came very fast."],"dok":2,"skill":"detail vs. key detail"},{"q":"Where does the main topic go in the Main Topic House?","answer":"on the roof","explanation":"Roof = main topic.","explanation_ar":"على السقف.","options":["in a room","on the roof","outside","in the garden"],"dok":1,"skill":"organizer"},{"q":"*When I grow up, I want to help people.* *Grow up* means ___.","answer":"become an adult","explanation":"Grow up = become an adult.","explanation_ar":"يكبر.","options":["get taller in one day","become an adult","go upstairs","wake up"],"dok":1,"skill":"vocabulary"},{"q":"Why does Adam write the letter?","answer":"to thank the firefighters","explanation":"First sentence: Thank you…","explanation_ar":"ليشكرهم.","options":["to ask for a new truck","to tell a funny story","to thank the firefighters","to sell a house"],"dok":2,"skill":"author's purpose"},{"q":"Which sentence is the best main topic for Adam's letter?","answer":"Adam thanks the firefighters for saving his neighbors.","explanation":"It covers the whole letter.","explanation_ar":"يغطي الرسالة كلها.","options":["Adam likes red.","Adam thanks the firefighters for saving his neighbors.","Firefighters have trucks.","Kitchens can be hot."],"dok":2,"skill":"main topic"},{"q":"Which sentence about Adam's future is correct?","answer":"When I grow up, I want to help people.","explanation":"When + grow up; want + to.","explanation_ar":"When I grow up + want to.","options":["When I will grow up, I want help people.","When grow up I, help people.","I want help when grow up.","When I grow up, I want to help people."],"dok":2,"skill":"usage"},{"q":"What would be a good title for the information text AND the letter together?","answer":"People Who Help Us","explanation":"Both are about helpers.","explanation_ar":"أشخاص يساعدوننا.","options":["People Who Help Us","Red Trucks","My Kitchen","Bread and Books"],"dok":3,"skill":"synthesize"},{"q":"What do Adam's words *You are brave and kind* show about his feelings?","answer":"He admires and thanks the firefighters.","explanation":"Praise shows admiration.","explanation_ar":"يُعجب بهم ويشكرهم.","options":["He is angry with them.","He is scared of them.","He admires and thanks the firefighters.","He is bored."],"dok":3,"skill":"inference"}],"images":[{"id":"IMG-RW-L02-U2-LS3-V01","prompt":"Picture for the word 'fire': small orange flames in a fireplace"},{"id":"IMG-RW-L02-U2-LS3-V02","prompt":"Picture for the word 'station': a fire station with big doors"},{"id":"IMG-RW-L02-U2-LS3-V03","prompt":"Picture for the word 'next to': two shops side by side"},{"id":"IMG-RW-L02-U2-LS3-V04","prompt":"Picture for the word 'hard work': a firefighter carrying a heavy hose"},{"id":"IMG-RW-L02-U2-LS3-V05","prompt":"Picture for the word 'grow up': a boy next to a taller shadow of himself in a uniform"},{"id":"IMG-RW-L02-U2-LS3-V06","prompt":"Picture for the word 'key detail': a key-shaped label on a small fact card"},{"id":"IMG-RW-L02-U2-LS3-V07","prompt":"Picture for the word 'again': a circular arrow"},{"id":"IMG-RW-L02-U2-LS3-01","prompt":"Adam holds up his thank-you letter and a drawing of a fire truck."},{"id":"IMG-RW-L02-U2-LS3-02","prompt":"A house drawing with a roof, three rooms and a garden."},{"id":"IMG-RW-L02-U2-LS3-03","prompt":"Firefighters put out a small kitchen fire while neighbors watch safely."}],"audio":[{"id":"AUD-RW-L02-U2-LS3-V01","script":"fire. The fire is very hot."},{"id":"AUD-RW-L02-U2-LS3-V02","script":"station. The fire station is on our street."},{"id":"AUD-RW-L02-U2-LS3-V03","script":"next to. The bakery is next to the mosque."},{"id":"AUD-RW-L02-U2-LS3-V04","script":"hard work. Thank you for your hard work."},{"id":"AUD-RW-L02-U2-LS3-V05","script":"grow up. When I grow up, I want to be a pilot."},{"id":"AUD-RW-L02-U2-LS3-V06","script":"key detail. Find three key details."},{"id":"AUD-RW-L02-U2-LS3-V07","script":"again. Thank you again!"},{"id":"AUD-RW-L02-U2-LS3-T1","script":"Dear Firefighters, Thank you for your hard work! Last week, there was a small fire in the kitchen of the house next to ours. You came very fast in your red truck. You put out the fire, and everyone was safe. You are brave and kind. When I grow up, I want to help people like you. Can I visit the fire station one day? Thank you again! Your friend, Adam Rahman"},{"id":"AUD-RW-L02-U2-LS3-VID","script":"Adam writes a letter. What is it ALL about? Dear Firefighters, Thank you for your hard work! Last week, there was a small fire… Clues: the title, the first sentence, the words we see many times – thank you! The main topic: Adam thanks the firefighters. Key details go in the rooms: a small fire, they came fast, everyone was safe. The red truck? True, but it is a small detail. Does it help us understand the main topic? Not much!"}]},{"id":"RW-L02-U2-LS4","title":"Writing Skill: Statements and questions","lesson_type":"writing_skill","objectives":["tell the difference between a statement (.) and a question (?)","write questions with question words (who, what, where, when, why, how) and with Is/Can/Do","put the verb before the subject in questions (Is the truck heavy?)"],"objectives_ar":["التمييز بين الجملة الخبرية (.) والجملة الاستفهامية (?).","كتابة أسئلة بأدوات الاستفهام وبـ Is/Can/Do.","وضع الفعل قبل الفاعل في الأسئلة."],"success_criteria":["I can tell a statement from a question.","I can end a question with a question mark.","I can write questions in the right order."],"success_criteria_ar":["أستطيع التمييز بين الجملة الخبرية والسؤال.","أستطيع إنهاء السؤال بعلامة استفهام.","أستطيع كتابة الأسئلة بالترتيب الصحيح."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"statement","pos":"noun","ipa":"/ˈsteɪtmənt/","definition":"a sentence that tells something","arabic":"جملة خبرية","example":"*The bakery is open.* is a statement.","image_id":"IMG-RW-L02-U2-LS4-V01","audio_id":"AUD-RW-L02-U2-LS4-V01","tier":"core"},{"word":"question","pos":"noun","ipa":"/ˈkwɛstʃən/","definition":"a sentence that asks something","arabic":"سؤال","example":"Do you have a question?","image_id":"IMG-RW-L02-U2-LS4-V02","audio_id":"AUD-RW-L02-U2-LS4-V02","tier":"core"},{"word":"question mark","pos":"noun","ipa":"/ˈkwɛstʃən mɑrk/","definition":"the mark ? at the end of a question","arabic":"علامة استفهام","example":"Put a question mark after a question.","image_id":"IMG-RW-L02-U2-LS4-V03","audio_id":"AUD-RW-L02-U2-LS4-V03","tier":"core"},{"word":"answer","pos":"noun","ipa":"/ˈænsər/","definition":"what you say or write back to a question","arabic":"إجابة","example":"Write your answer here.","image_id":"IMG-RW-L02-U2-LS4-V04","audio_id":"AUD-RW-L02-U2-LS4-V04","tier":"core"},{"word":"how many","pos":"phrase","ipa":"/haʊ ˈmɛni/","definition":"a question about a number","arabic":"كم (للعدد)","example":"How many books do you have?","image_id":"IMG-RW-L02-U2-LS4-V05","audio_id":"AUD-RW-L02-U2-LS4-V05","tier":"core"},{"word":"when","pos":"adverb","ipa":"/wɛn/","definition":"a question word about time","arabic":"متى","example":"When does the library open?","image_id":"IMG-RW-L02-U2-LS4-V06","audio_id":"AUD-RW-L02-U2-LS4-V06","tier":"core"},{"word":"heavy","pos":"adjective","ipa":"/ˈhɛvi/","definition":"difficult to lift; weighing a lot","arabic":"ثقيل","example":"The fire hose is heavy.","image_id":"IMG-RW-L02-U2-LS4-V07","audio_id":"AUD-RW-L02-U2-LS4-V07","tier":"core"}],"explanation":{"text":"A **statement** tells something. It ends with a **period** (.): *The bakery is open.*\n\nA **question** asks something. It ends with a **question mark** (?): *Is the bakery open?*\n\nQuestions often start with a **question word** (*Who, What, Where, When, Why, How, How many*) or with **Is / Are / Can / Do / Does**.\n\nIn a question, the helping verb comes **before** the subject: *The truck **is** heavy.* → ***Is** the truck heavy?*","examples":["Statement: **The library is near the mosque.** → Question: **Is the library near the mosque?**","Statement: **The nurse works at night.** → Question: **When does the nurse work?**","Statement: **Firefighters are brave.** → Question: **Are firefighters brave?**","Statement: **I can visit the fire station.** → Question: **Can I visit the fire station?**","**Who** makes the bread? → The baker.","**Where** do doctors work? → At the hospital.","**Why** do police officers stop the cars? → To keep children safe.","**How many** firefighters work here? → Ten.","Statement with strong feeling: **The fire truck is huge!**"],"common_errors":["✗ Where the hospital is? → ✓ Where is the hospital? (Put **is** before the subject in questions.)","✗ You can help me? → ✓ Can you help me? (Put **Can** first.)","✗ What time the shop opens? → ✓ What time does the shop open? (Use **does** + plain verb.)","✗ Is the truck heavy. → ✓ Is the truck heavy? (A question needs a **question mark**.)","✗ The bakery is open? → ✓ The bakery is open. (A statement ends with a period.)","✗ How much firefighters? → ✓ How many firefighters? (Use **how many** for things you can count.)","✗ ؟ (Arabic question mark) → ✓ ? (In English, the question mark faces the other way: **?**)"],"arabic":"الجملة الخبرية تخبرنا بشيء وتنتهي بنقطة: The bakery is open.\n\nالسؤال يطلب معلومة وينتهي بعلامة استفهام: Is the bakery open?\n\nتبدأ الأسئلة غالبًا بأداة استفهام (Who, What, Where, When, Why, How) أو بـ Is/Are/Can/Do/Does.\n\nفي السؤال يأتي الفعل المساعد قبل الفاعل: The truck is heavy ← Is the truck heavy?\n\nانتبه: علامة الاستفهام الإنجليزية ? تتجه عكس العربية ؟."},"video":{"script":[{"time":"00:00–00:15","narration":"Tell or ask? Statements tell. Questions ask!","on_screen":"Statement . | Question ?","visual":"Saqr holds a period sign in one wing and a question-mark sign in the other."},{"time":"00:15–00:45","narration":"The bakery is open. – That tells. Period! Is the bakery open? – That asks. Question mark!","on_screen":". vs ?","visual":"The same words reorder; the period flips into a question mark."},{"time":"00:45–01:20","narration":"Watch the swap! The truck IS heavy. → IS the truck heavy?","on_screen":"Swap: is ↔ the truck","visual":"The word 'is' jumps to the front of the sentence."},{"time":"01:20–01:55","narration":"Question words: Who? What? Where? When? Why? How many?","on_screen":"Who · What · Where · When · Why · How many","visual":"Six question-word cards spin around a fire station."},{"time":"01:55–02:20","narration":"Careful! The English question mark faces this way: ? Not like Arabic ؟","on_screen":"? not ؟","visual":"The Arabic mark turns around to become the English one."},{"time":"02:20–02:40","narration":"Adam writes questions for the fire station visit. Now you write yours!","on_screen":"Your questions?","visual":"Adam holds his notebook with four questions."}],"captions_ar":["تخبر أم تسأل؟ الجمل الخبرية تخبر، والأسئلة تسأل!","المخبز مفتوح: هذه تخبر فنضع نقطة. هل المخبز مفتوح؟ هذه تسأل فنضع علامة استفهام!","انظروا إلى التبديل: The truck is heavy ← Is the truck heavy?","أدوات الاستفهام: من؟ ماذا؟ أين؟ متى؟ لماذا؟ كم؟","انتبه! علامة الاستفهام الإنجليزية تتجه هكذا ? وليس مثل العربية ؟","آدم يكتب أسئلة لزيارة محطة الإطفاء. والآن اكتب أسئلتك!"],"voice":"Narrator: American English, warm female teacher, speed 0.85, with rising intonation on questions. Adam: curious boy voice."},"texts":[{"type":"model","title":"My Fire Station Visit (from Adam's Notebook)","body":"Tomorrow, our class visits the fire station. I am excited. I have some questions for the firefighters.\n\nHow many firefighters work here? When do you sleep? Is the fire truck heavy? Can I sit in the truck?\n\nI want to be brave like them!","word_count":44,"audio_id":"AUD-RW-L02-U2-LS4-T1","id":"TXT-RW-L02-U2-LS4-1","genre":"model text","role":"model","difficulty":"200L–350L","glossary":[],"annotations":["**I am excited.** – a **statement** tells something. It ends with a **period** (.).","**How many firefighters work here?** – a **question** asks something. It ends with a **question mark** (?).","**Is the fire truck heavy?** – a question can start with **Is**, **Are**, **Can** or **Do**.","**When do you sleep?** – a question can start with a question word: **Who, What, Where, When, Why, How**.","**I want to be brave like them!** – a strong feeling can end with an **exclamation mark** (!)."]}],"activities":[{"id":"RW-L02-U2-LS4-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Statement or question? Choose the right end mark.","instructions_ar":"خبرية أم سؤال؟ اختر علامة النهاية الصحيحة.","items":[{"q":"*Where is the fire station* needs ___.","answer":"a question mark (?)","explanation":"It asks something.","explanation_ar":"تسأل.","options":["a question mark (?)","a period (.)","a comma (,)","nothing"],"dok":1,"skill":"end marks","stage":"controlled"},{"q":"*The bakery opens at six* needs ___.","answer":"a period (.)","explanation":"It tells something.","explanation_ar":"تخبر.","options":["a question mark (?)","a comma (,)","a period (.)","nothing"],"dok":1,"skill":"end marks","stage":"controlled"},{"q":"*Can I borrow this book* needs ___.","answer":"a question mark (?)","explanation":"It starts with Can and asks.","explanation_ar":"تبدأ بـ Can.","options":["a period (.)","a comma (,)","a question mark (?)","nothing"],"dok":1,"skill":"end marks","stage":"controlled"},{"q":"Which one is a statement?","answer":"The nurse is kind.","explanation":"It tells something.","explanation_ar":"تخبر.","options":["Is the nurse kind?","The nurse is kind.","Where is the nurse?","Who is the nurse?"],"dok":1,"skill":"statements","stage":"controlled"},{"q":"Which one is a question?","answer":"When does the mosque open?","explanation":"It asks something.","explanation_ar":"تسأل.","options":["The mosque opens early.","The mosque is big.","I go to the mosque.","When does the mosque open?"],"dok":1,"skill":"questions","stage":"controlled"},{"q":"Which question word asks about a number?","answer":"How many","explanation":"How many = number.","explanation_ar":"How many للعدد.","options":["Where","Who","Why","How many"],"dok":1,"skill":"question words","stage":"controlled"}]},{"id":"RW-L02-U2-LS4-A2","type":"open","stage":"guided","instructions":"Guided practice: Change each statement into a question.","instructions_ar":"حوّل كل جملة خبرية إلى سؤال.","items":[{"q":"The truck is heavy.","answer":"Is the truck heavy?","explanation":"Swap is and the truck.","explanation_ar":"بدّل is مع the truck.","dok":1,"skill":"forming questions","stage":"guided"},{"q":"The library is open.","answer":"Is the library open?","explanation":"Swap.","explanation_ar":"بدّل.","dok":1,"skill":"forming questions","stage":"guided"},{"q":"The firefighters are brave.","answer":"Are the firefighters brave?","explanation":"Swap are.","explanation_ar":"بدّل are.","dok":1,"skill":"forming questions","stage":"guided"},{"q":"I can visit the station.","answer":"Can I visit the station?","explanation":"Can goes first.","explanation_ar":"Can أولًا.","dok":2,"skill":"forming questions","stage":"guided"},{"q":"You can help me.","answer":"Can you help me?","explanation":"Can goes first.","explanation_ar":"Can أولًا.","dok":2,"skill":"forming questions","stage":"guided"},{"q":"The baker is busy.","answer":"Is the baker busy?","explanation":"Swap is.","explanation_ar":"بدّل is.","dok":1,"skill":"forming questions","stage":"guided"}]},{"id":"RW-L02-U2-LS4-A3","type":"open","stage":"freer","instructions":"Freer practice: Fix the questions.","instructions_ar":"صحّح الأسئلة.","items":[{"q":"Where the hospital is?","answer":"Where is the hospital?","explanation":"is before the hospital.","explanation_ar":"is قبل the hospital.","dok":2,"skill":"editing","stage":"freer"},{"q":"You can open the door?","answer":"Can you open the door?","explanation":"Can first.","explanation_ar":"Can أولًا.","dok":2,"skill":"editing","stage":"freer"},{"q":"Is the nurse kind.","answer":"Is the nurse kind?","explanation":"Use a question mark.","explanation_ar":"علامة استفهام.","dok":1,"skill":"editing","stage":"freer"},{"q":"How much doctors work here?","answer":"How many doctors work here?","explanation":"How many for counting.","explanation_ar":"How many للعدّ.","dok":2,"skill":"editing","stage":"freer"}]},{"id":"RW-L02-U2-LS4-A4","type":"open","stage":"production","instructions":"Writing: Write questions for a community helper.","instructions_ar":"اكتب أسئلة لمساعد في المجتمع.","items":[{"q":"Write a Where question.","answer":"Where do you work?","explanation":"Where + do/is…?","explanation_ar":"Where + do/is.","dok":1,"skill":"writing questions","stage":"production"},{"q":"Write a When question.","answer":"When do you start work?","explanation":"When + do…?","explanation_ar":"When + do.","dok":2,"skill":"writing questions","stage":"production"},{"q":"Write an Is or Can question.","answer":"Is your job hard?","explanation":"Is/Can first.","explanation_ar":"Is/Can أولًا.","dok":2,"skill":"writing questions","stage":"production"},{"q":"Write a How many question.","answer":"How many people do you help every day?","explanation":"How many + noun + do…?","explanation_ar":"How many + اسم.","dok":2,"skill":"writing questions","stage":"production"}]}],"game":{"name":"Question Swap Race","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Swap puzzle: a statement appears as tiles; the child drags the helping verb to the front and swaps the period for a question mark. Correct = the sentence 'speaks' with question intonation.","Each pair gets an envelope and builds the statement first.","On \"Swap!\", they move one card to make a question and change the end mark.","They read the question aloud with a rising voice.","First correct pair = 2 points; other correct pairs = 1 point.","Six rounds."],"data":[]},"exit_quiz":[{"q":"A question ends with ___.","answer":"a question mark (?)","explanation":"Questions end with ?.","explanation_ar":"علامة استفهام.","options":["a period (.)","a comma (,)","a capital letter","a question mark (?)"],"dok":1,"skill":"end marks"},{"q":"A statement ___.","answer":"tells something","explanation":"Statements tell.","explanation_ar":"تخبر.","options":["asks something","tells something","has no words","is always long"],"dok":1,"skill":"statements"},{"q":"Which question about the bakery is in the right order?","answer":"Is the bakery open?","explanation":"Is + subject + describing word.","explanation_ar":"Is + الفاعل + الصفة.","options":["Is the bakery open?","The bakery is open?","Open is the bakery?","Is open the bakery?"],"dok":1,"skill":"question order"},{"q":"Which question word asks about time?","answer":"When","explanation":"When = time.","explanation_ar":"When للزمن.","options":["Who","Where","When","What"],"dok":1,"skill":"question words"},{"q":"Which question word do you use to ask about a building's place?","answer":"Where","explanation":"Where = place.","explanation_ar":"Where للمكان.","options":["Where","Who","When","How many"],"dok":1,"skill":"question words"},{"q":"Turn into a question: *You can help me.*","answer":"Can you help me?","explanation":"Can goes first.","explanation_ar":"Can أولًا.","options":["You can help me?","Help me you can?","Can you help me?","Can help you me?"],"dok":2,"skill":"forming questions"},{"q":"Fix: *Where the library is?*","answer":"Where is the library?","explanation":"is before the subject.","explanation_ar":"is قبل الفاعل.","options":["Where the library?","Where library is?","Is where the library?","Where is the library?"],"dok":2,"skill":"editing"},{"q":"Which question uses *how many* correctly?","answer":"How many nurses work here?","explanation":"How many + things you can count.","explanation_ar":"How many للأشياء المعدودة.","options":["How many water is here?","How much nurses work here?","How many is the nurse?","How many nurses work here?"],"dok":2,"skill":"question words"},{"q":"In Adam's model, which sentence is a statement?","answer":"I am excited.","explanation":"It tells his feeling.","explanation_ar":"تخبر بشعوره.","options":["When do you sleep?","I am excited.","Is the fire truck heavy?","Can I sit in the truck?"],"dok":2,"skill":"statements"},{"q":"Why does Adam write questions before the visit?","answer":"to be ready to learn from the firefighters","explanation":"Questions help him learn on the visit.","explanation_ar":"ليستعد للتعلم.","options":["to be ready to learn from the firefighters","to make the letter longer","to practice periods","to draw a truck"],"dok":3,"skill":"purpose"}],"images":[{"id":"IMG-RW-L02-U2-LS4-V01","prompt":"Picture for the word 'statement': a speech bubble with a period at the end"},{"id":"IMG-RW-L02-U2-LS4-V02","prompt":"Picture for the word 'question': a speech bubble with a question mark"},{"id":"IMG-RW-L02-U2-LS4-V03","prompt":"Picture for the word 'question mark': a big question mark"},{"id":"IMG-RW-L02-U2-LS4-V04","prompt":"Picture for the word 'answer': a hand raised with a light bulb"},{"id":"IMG-RW-L02-U2-LS4-V05","prompt":"Picture for the word 'how many': a child counting books"},{"id":"IMG-RW-L02-U2-LS4-V06","prompt":"Picture for the word 'when': a clock with a question mark"},{"id":"IMG-RW-L02-U2-LS4-V07","prompt":"Picture for the word 'heavy': two firefighters lifting a heavy hose"},{"id":"IMG-RW-L02-U2-LS4-01","prompt":"Adam's notebook with question-mark doodles and a fire truck."},{"id":"IMG-RW-L02-U2-LS4-02","prompt":"Word blocks swapping places to make a question."},{"id":"IMG-RW-L02-U2-LS4-03","prompt":"English and Arabic question marks facing opposite ways."}],"audio":[{"id":"AUD-RW-L02-U2-LS4-V01","script":"statement. *The bakery is open.* is a statement."},{"id":"AUD-RW-L02-U2-LS4-V02","script":"question. Do you have a question?"},{"id":"AUD-RW-L02-U2-LS4-V03","script":"question mark. Put a question mark after a question."},{"id":"AUD-RW-L02-U2-LS4-V04","script":"answer. Write your answer here."},{"id":"AUD-RW-L02-U2-LS4-V05","script":"how many. How many books do you have?"},{"id":"AUD-RW-L02-U2-LS4-V06","script":"when. When does the library open?"},{"id":"AUD-RW-L02-U2-LS4-V07","script":"heavy. The fire hose is heavy."},{"id":"AUD-RW-L02-U2-LS4-T1","script":"Tomorrow, our class visits the fire station. I am excited. I have some questions for the firefighters. How many firefighters work here? When do you sleep? Is the fire truck heavy? Can I sit in the truck? I want to be brave like them!"},{"id":"AUD-RW-L02-U2-LS4-VID","script":"Tell or ask? Statements tell. Questions ask! The bakery is open. – That tells. Period! Is the bakery open? – That asks. Question mark! Watch the swap! The truck IS heavy. → IS the truck heavy? Question words: Who? What? Where? When? Why? How many? Careful! The English question mark faces this way: ? Not like Arabic ؟ Adam writes questions for the fire station visit. Now you write yours!"}]},{"id":"RW-L02-U2-LS5","title":"Writing Workshop: A thank-you letter to a community helper","lesson_type":"writing_workshop","objectives":["plan a thank-you letter to a community helper: who, what they do, why we are thankful","write a letter of 5–6 sentences with a greeting, a thank-you sentence, reasons with because, a question and a closing","edit for end marks (. ? !), capitals and commas, then deliver the letter"],"objectives_ar":["التخطيط لرسالة شكر لمساعد في المجتمع: مَن، وماذا يفعل، ولماذا نشكره.","كتابة رسالة من 5–6 جمل فيها تحية وجملة شكر وأسباب بـ because وسؤال وخاتمة.","تدقيق علامات النهاية والحروف الكبيرة والفواصل، ثم تسليم الرسالة."],"success_criteria":["I can plan who I will thank and why.","I can write a thank-you letter with all its parts.","I can check periods, question marks, capitals and commas."],"success_criteria_ar":["أستطيع التخطيط لمن سأشكر ولماذا.","أستطيع كتابة رسالة شكر بكل أجزائها.","أستطيع مراجعة النقاط وعلامات الاستفهام والحروف الكبيرة والفواصل."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"thank-you letter","pos":"noun","ipa":"/ˈθæŋk ju ˈlɛtər/","definition":"a letter to say thank you","arabic":"رسالة شكر","example":"I write a thank-you letter to my teacher.","image_id":"IMG-RW-L02-U2-LS5-V01","audio_id":"AUD-RW-L02-U2-LS5-V01","tier":"core"},{"word":"Sincerely","pos":"adverb","ipa":"/sɪnˈsɪrli/","definition":"a polite way to end a letter","arabic":"مع خالص التحية","example":"Sincerely, Noura","image_id":"IMG-RW-L02-U2-LS5-V02","audio_id":"AUD-RW-L02-U2-LS5-V02","tier":"core"},{"word":"deliver","pos":"verb","ipa":"/dɪˈlɪvər/","definition":"to take something to a person","arabic":"يوصل / يسلّم","example":"The mail carrier delivers letters.","image_id":"IMG-RW-L02-U2-LS5-V03","audio_id":"AUD-RW-L02-U2-LS5-V03","tier":"core"},{"word":"keep","pos":"verb","ipa":"/kip/","definition":"to make something stay the same (keep us safe)","arabic":"يحافظ على / يُبقي","example":"Police officers keep us safe.","image_id":"IMG-RW-L02-U2-LS5-V04","audio_id":"AUD-RW-L02-U2-LS5-V04","tier":"core"},{"word":"clean","pos":"verb","ipa":"/klin/","definition":"to make something not dirty","arabic":"ينظّف","example":"Workers clean our streets.","image_id":"IMG-RW-L02-U2-LS5-V05","audio_id":"AUD-RW-L02-U2-LS5-V05","tier":"core"},{"word":"care for","pos":"verb","ipa":"/kɛr fɔr/","definition":"to look after","arabic":"يعتني بـ","example":"Nurses care for sick children.","image_id":"IMG-RW-L02-U2-LS5-V06","audio_id":"AUD-RW-L02-U2-LS5-V06","tier":"core"},{"word":"hard-working","pos":"adjective","ipa":"/ˌhɑrdˈwɝkɪŋ/","definition":"working a lot and doing a good job","arabic":"مجتهد","example":"Our baker is hard-working.","image_id":"IMG-RW-L02-U2-LS5-V07","audio_id":"AUD-RW-L02-U2-LS5-V07","tier":"core"}],"explanation":{"text":"A **thank-you letter** tells a person that we are **thankful** for their help.\n\nParts: **greeting** (Dear ___,) → **thank-you sentence** → **reasons with because** (1–2) → **a question** → **closing** (Sincerely, / Your friend,) → **your name**.\n\nUse the right end marks: **.** for statements, **?** for your question and **!** for a strong feeling.","examples":["Greeting: **Dear Nurse Hala,**","Thank-you sentence: **Thank you for caring for me at the hospital.**","Reason: **You are kind because you smile at every child.**","Reason: **I felt better because you gave me medicine on time.**","Question: **Do you work every night?**","Strong feeling: **You are the best nurse!**","Closing: **Sincerely,** / **Your friend,**","Name: **Faris Al-Otaibi**","Another helper: **Dear Uncle Saeed (our baker), thank you for the fresh bread every morning.**"],"common_errors":["✗ Dear nurse hala → ✓ Dear Nurse Hala, (Capitals for the name and title; comma after it.)","✗ Thank you for help me. → ✓ Thank you for helping me. (After **for**, use **-ing**.)","✗ Do you work every night. → ✓ Do you work every night? (A question needs **?**.)","✗ Sincerely Faris (one line) → ✓ Sincerely, / Faris (Comma after Sincerely; name on the next line.)","✗ You are kind because smile. → ✓ You are kind because you smile. (After because: who + action.)","✗ I thank you very. → ✓ Thank you very much. (Say **very much**.)"],"arabic":"رسالة الشكر تخبر الشخص بأننا ممتنون لمساعدته.\n\nأجزاؤها: التحية، ثم جملة الشكر، ثم سبب أو سببان بـ because، ثم سؤال، ثم الخاتمة (Sincerely,)، ثم اسمك.\n\nاستخدم علامات النهاية الصحيحة: النقطة للخبر، وعلامة الاستفهام للسؤال، وعلامة التعجب للشعور القوي.\n\nانتبه: نقول Thank you for helping me بإضافة ing بعد for."},"video":{"script":[{"time":"00:00–00:15","narration":"Noura wants to thank Ms. Huda, the school librarian.","on_screen":"A Thank-You Letter","visual":"Noura in the school library holding a favorite book; Ms. Huda shelves books."},{"time":"00:15–00:45","narration":"Plan: Who? Ms. Huda. What does she do? Helps us find books. Why thank her? She is patient and kind.","on_screen":"1 Plan – who · what · why","visual":"Three icons fill: a person, a book, a heart."},{"time":"00:45–01:30","narration":"Draft: Dear Ms. Huda, Thank you for helping me find good books. You are kind because you always smile. I love reading because of you! Do you have a favorite book? Sincerely, Noura","on_screen":"2 Draft – all parts","visual":"The letter builds part by part with colored brackets."},{"time":"01:30–01:55","narration":"Revise: add one more reason – I read faster now because you help me choose easy books.","on_screen":"3 Revise ➕ reason","visual":"A new green sentence slides in."},{"time":"01:55–02:20","narration":"Edit: period, question mark, exclamation mark – check! Comma after Dear Ms. Huda and Sincerely – check!","on_screen":"4 Edit . ? ! ,","visual":"End marks glow one by one."},{"time":"02:20–02:50","narration":"Publish: Noura puts the letter in an envelope and delivers it. Ms. Huda smiles!","on_screen":"5 Deliver ✉️","visual":"Ms. Huda opens the envelope and puts her hand on her heart."}],"captions_ar":["تريد نورة أن تشكر الأستاذة هدى أمينة مكتبة المدرسة.","التخطيط: من؟ الأستاذة هدى. ماذا تفعل؟ تساعدنا في إيجاد الكتب. لماذا نشكرها؟ صبورة ولطيفة.","المسودة: عزيزتي الأستاذة هدى، شكرًا لمساعدتي في إيجاد كتب جيدة. أنتِ لطيفة لأنك تبتسمين دائمًا…","التحسين: أضف سببًا آخر.","التدقيق: النقطة وعلامة الاستفهام وعلامة التعجب والفواصل.","النشر: تضع نورة الرسالة في ظرف وتسلّمها، فتبتسم الأستاذة هدى!"],"voice":"Narrator: American English, warm female teacher, speed 0.85. Noura reads her letter to the school librarian in a polite, warm voice."},"texts":[],"activities":[{"id":"RW-L02-U2-LS5-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the best answer.","instructions_ar":"اختر أفضل إجابة.","items":[{"q":"Which greeting is best for a letter to a nurse called Hala?","answer":"Dear Nurse Hala,","explanation":"Capitals + comma.","explanation_ar":"حروف كبيرة وفاصلة.","options":["dear nurse hala","Dear Nurse Hala,","Dear Nurse Hala.","Hala nurse dear,"],"dok":1,"skill":"letter parts","stage":"controlled"},{"q":"Which sentence says thank you correctly?","answer":"Thank you for helping me.","explanation":"for + -ing.","explanation_ar":"for + ing.","options":["Thank you for help me.","Thank you for helping me.","Thank for you help.","You thank for helping."],"dok":1,"skill":"usage","stage":"controlled"},{"q":"Which is a polite closing?","answer":"Sincerely,","explanation":"Sincerely is polite.","explanation_ar":"Sincerely مهذبة.","options":["Goodbye!","The end.","Sincerely,","Dear,"],"dok":1,"skill":"letter parts","stage":"controlled"},{"q":"A person who works a lot and does a good job is ___.","answer":"hard-working","explanation":"Hard-working = works a lot.","explanation_ar":"مجتهد.","options":["hard-working","heavy","bored","sick"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Mail carriers ___ letters to our houses.","answer":"deliver","explanation":"Deliver = take to a person.","explanation_ar":"يوصلون.","options":["clean","care for","deliver","keep"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Which sentence in a thank-you letter needs a question mark?","answer":"Do you like your job","explanation":"It asks something.","explanation_ar":"تسأل.","options":["You are very kind","Thank you for the bread","I am thankful","Do you like your job"],"dok":2,"skill":"end marks","stage":"controlled"}]},{"id":"RW-L02-U2-LS5-A2","type":"sequence","stage":"guided","instructions":"Put in order: Put the parts of the letter in order.","instructions_ar":"رتّب أجزاء الرسالة.","items":[{"q":"Order Lama's letter to Mr. Fahad.","answer":"Dear Mr. Fahad, → Thank you for the weather news. → Is your job fun? → Sincerely, Lama","explanation":"Greeting → thank you → question → closing.","explanation_ar":"تحية ← شكر ← سؤال ← خاتمة.","stage":"guided","parts":["Sincerely, Lama","Thank you for the weather news.","Dear Mr. Fahad,","Is your job fun?"],"target":["Dear Mr. Fahad,","Thank you for the weather news.","Is your job fun?","Sincerely, Lama"]},{"q":"Build a thank-you sentence for a police officer.","answer":"Thank you for keeping us safe.","explanation":"Thank you for + -ing.","explanation_ar":"Thank you for + ing.","stage":"guided","parts":["for","us","you","Thank","safe.","keeping"],"target":["Thank","you","for","keeping","us","safe."]},{"q":"Build a reason sentence about smiling.","answer":"You are kind because you smile.","explanation":"Reason with because.","explanation_ar":"سبب بـ because.","stage":"guided","parts":["you","because","are","kind","You","smile."],"target":["You","are","kind","because","you","smile."]},{"q":"Build a question about working at night.","answer":"Do you work at night?","explanation":"Do + you + verb…?","explanation_ar":"Do + you + فعل.","stage":"guided","parts":["Do","at","night?","work","you"],"target":["Do","you","work","at","night?"]},{"q":"Build a thank-you sentence for a street cleaner.","answer":"Thank you for cleaning our street.","explanation":"Thank you for + -ing.","explanation_ar":"Thank you for + ing.","stage":"guided","parts":["street.","our","for","cleaning","Thank","you"],"target":["Thank","you","for","cleaning","our","street."]},{"q":"Build a strong-feeling sentence for a baker.","answer":"You are the best baker!","explanation":"Strong feeling with !","explanation_ar":"شعور قوي بـ !","stage":"guided","parts":["the","You","are","best","baker!"],"target":["You","are","the","best","baker!"]}]},{"id":"RW-L02-U2-LS5-A3","type":"organizer","stage":"freer","instructions":"Organizer: Plan your letter.","instructions_ar":"خطط لرسالتك.","items":[{"q":"Who will you thank?","answer":"the bus driver, Uncle Mansour","explanation":"A real helper.","explanation_ar":"مساعد حقيقي.","dok":1,"skill":"planning","stage":"freer"},{"q":"What does he or she do?","answer":"He drives us to school every morning.","explanation":"The helper's job.","explanation_ar":"عمله.","dok":1,"skill":"planning","stage":"freer"},{"q":"Why are you thankful? Use because.","answer":"I am thankful because he drives carefully and we are safe.","explanation":"because + reason.","explanation_ar":"because + سبب.","dok":2,"skill":"planning","stage":"freer"},{"q":"Write one question for the helper.","answer":"How many children ride your bus?","explanation":"A question with ?","explanation_ar":"سؤال بـ ?","dok":2,"skill":"planning","stage":"freer"}]},{"id":"RW-L02-U2-LS5-A4","type":"writing","stage":"production","instructions":"Writing: Write your thank-you letter. Then edit and deliver it.","instructions_ar":"اكتب رسالة الشكر ثم دققها وسلّمها.","items":[{"q":"Write your greeting and your thank-you sentence.","answer":"Dear Uncle Mansour, Thank you for driving us to school.","explanation":"Greeting + thank-you sentence.","explanation_ar":"تحية + شكر.","dok":1,"skill":"writing","stage":"production"},{"q":"Write one or two reasons with because.","answer":"We are safe because you drive carefully. You are kind because you wait for us.","explanation":"Complete because sentences.","explanation_ar":"جمل because كاملة.","dok":2,"skill":"writing","stage":"production"},{"q":"Write your question and a strong feeling sentence.","answer":"How many children ride your bus? You are the best driver!","explanation":"? and !","explanation_ar":"? و!","dok":2,"skill":"writing","stage":"production"},{"q":"Write the closing and your name for your thank-you letter.","answer":"Sincerely, Sami","explanation":"Closing + comma + name.","explanation_ar":"خاتمة + فاصلة + اسم.","dok":1,"skill":"writing","stage":"production","_w":{"checklist":[],"min":null,"max":null}}]},{"id":"RW-L02-U2-LS5-ORG","type":"organizer","organizer":"Thank-You Letter Plan","instructions":"Organizer: Answer the three questions. Then add a question you want to ask.","items":[{"q":"Who will I thank?","answer":"Nurse Hala"},{"q":"What does he or she do?","answer":"cares for sick children at the hospital"},{"q":"Why am I thankful? (because…)","answer":"she is kind and she helped me get better"},{"q":"My question for him or her","answer":"Do you work every night?"}]},{"id":"RW-L02-U2-LS5-WR","type":"writing","instructions":"Writing: Write a thank-you letter (5–6 sentences) to a helper in your school or neighborhood. Write a thank-you letter (5–6 sentences) to a helper in your school or neighborhood.","instructions_ar":"اكتب رسالة شكر (5–6 جمل) لمساعد في مدرستك أو حيّك.","prompt":"Write a thank-you letter (5–6 sentences) to a helper in your school or neighborhood.","checklist":["I wrote a greeting with capitals and a comma.","I wrote a thank-you sentence.","I gave at least one reason with because.","I wrote one question with a question mark.","Statements end with a period.","I wrote a closing with a comma and my name."],"rubric_id":"RW-RUBRIC-5T","min_words":35,"max_words":90,"organizer":"Thank-You Letter Plan (who – what – why – question)","items":[{"q":"Write a thank-you letter (5–6 sentences) to a helper in your school or neighborhood.","answer":"Dear Ms. Huda, Thank you for helping me find good books. You are kind because you always smile at us. I read faster now because you help me choose the right books. Do you have a favorite book? You are the best librarian! Sincerely, Noura","_w":{"checklist":["I wrote a greeting with capitals and a comma.","I wrote a thank-you sentence.","I gave at least one reason with because.","I wrote one question with a question mark.","Statements end with a period.","I wrote a closing with a comma and my name."],"min":35,"max":90}}]}],"game":{"name":"End Mark Toss","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Punctuation pop: a sentence floats up without an end mark; the child taps . ? or ! Correct = the sentence lands in a letter; three wrong = the letter blows away (try again).","Teams line up.","A player reads a sentence card aloud with the right voice (telling, asking or excited).","The player throws a bean bag into the bucket with the right end mark.","Correct bucket = 1 point; correct voice = 1 bonus point.","Play 12 cards."],"data":[]},"exit_quiz":[{"q":"What does a thank-you letter tell a person?","answer":"that we are thankful for their help","explanation":"It says thank you.","explanation_ar":"أننا ممتنون.","options":["how to bake bread","a funny story","the weather","that we are thankful for their help"],"dok":1,"skill":"genre"},{"q":"Which part comes right after the greeting?","answer":"the thank-you sentence","explanation":"Greeting → thank-you sentence.","explanation_ar":"جملة الشكر.","options":["the closing","the thank-you sentence","the name","the question"],"dok":1,"skill":"letter parts"},{"q":"Which sentence uses *because* correctly?","answer":"You are kind because you help everyone.","explanation":"because + who + action.","explanation_ar":"سبب كامل.","options":["You are kind because help everyone.","Because you are kind.","You kind because.","You are kind because you help everyone."],"dok":2,"skill":"complete sentences"},{"q":"Which closing for a thank-you letter is correct?","answer":"Sincerely,","explanation":"Capital S + comma.","explanation_ar":"S كبيرة وفاصلة.","options":["sincerely","Sincerely.","Sincerely,","Sincerely!"],"dok":1,"skill":"punctuation"},{"q":"*Nurses care for sick children.* *Care for* means ___.","answer":"look after","explanation":"Care for = look after.","explanation_ar":"يعتني بـ.","options":["look after","run after","break","count"],"dok":1,"skill":"vocabulary"},{"q":"Which sentence needs an exclamation mark?","answer":"You are the best teacher","explanation":"A strong feeling.","explanation_ar":"شعور قوي.","options":["You are the best teacher","Do you like books","I go to school","The bus is blue"],"dok":2,"skill":"end marks"},{"q":"Fix: *Thank you for drive us.*","answer":"Thank you for driving us.","explanation":"for + -ing.","explanation_ar":"for + ing.","options":["Thank you for drove us.","Thank you for driving us.","Thank you drive us.","Thanks you for drive us."],"dok":2,"skill":"editing"},{"q":"Why do we put a question in a thank-you letter?","answer":"to show interest and start a conversation","explanation":"Questions show we care.","explanation_ar":"لنظهر الاهتمام.","options":["to show interest and start a conversation","to make it longer only","to be rude","to end the letter"],"dok":2,"skill":"purpose"},{"q":"Which helper would you thank for *keeping our streets clean*?","answer":"a street cleaner","explanation":"Street cleaners clean streets.","explanation_ar":"عامل النظافة.","options":["a librarian","a pilot","a baker","a street cleaner"],"dok":2,"skill":"apply"},{"q":"Which letter is the most complete?","answer":"greeting, thank-you sentence, a because reason, a question, closing and name","explanation":"It has all the parts.","explanation_ar":"فيها كل الأجزاء.","options":["a greeting only","a name and a picture","greeting, thank-you sentence, a because reason, a question, closing and name","one sentence with no greeting"],"dok":3,"skill":"evaluate"}],"images":[{"id":"IMG-RW-L02-U2-LS5-V01","prompt":"Picture for the word 'thank-you letter': an envelope with a heart sticker"},{"id":"IMG-RW-L02-U2-LS5-V02","prompt":"Picture for the word 'Sincerely': the end of a letter with a signature"},{"id":"IMG-RW-L02-U2-LS5-V03","prompt":"Picture for the word 'deliver': a mail carrier handing a letter at a door"},{"id":"IMG-RW-L02-U2-LS5-V04","prompt":"Picture for the word 'keep': a police officer watching over a school crossing"},{"id":"IMG-RW-L02-U2-LS5-V05","prompt":"Picture for the word 'clean': a street cleaner sweeping a sidewalk"},{"id":"IMG-RW-L02-U2-LS5-V06","prompt":"Picture for the word 'care for': a nurse caring for a child in bed"},{"id":"IMG-RW-L02-U2-LS5-V07","prompt":"Picture for the word 'hard-working': a baker smiling with many loaves"},{"id":"IMG-RW-L02-U2-LS5-01","prompt":"Noura gives a thank-you letter to Ms. Huda in the library."},{"id":"IMG-RW-L02-U2-LS5-02","prompt":"A letter with colored brackets marking its parts."},{"id":"IMG-RW-L02-U2-LS5-03","prompt":"Five school helpers standing in a row."}],"audio":[{"id":"AUD-RW-L02-U2-LS5-V01","script":"thank-you letter. I write a thank-you letter to my teacher."},{"id":"AUD-RW-L02-U2-LS5-V02","script":"Sincerely. Sincerely, Noura"},{"id":"AUD-RW-L02-U2-LS5-V03","script":"deliver. The mail carrier delivers letters."},{"id":"AUD-RW-L02-U2-LS5-V04","script":"keep. Police officers keep us safe."},{"id":"AUD-RW-L02-U2-LS5-V05","script":"clean. Workers clean our streets."},{"id":"AUD-RW-L02-U2-LS5-V06","script":"care for. Nurses care for sick children."},{"id":"AUD-RW-L02-U2-LS5-V07","script":"hard-working. Our baker is hard-working."},{"id":"AUD-RW-L02-U2-LS5-VID","script":"Noura wants to thank Ms. Huda, the school librarian. Plan: Who? Ms. Huda. What does she do? Helps us find books. Why thank her? She is patient and kind. Draft: Dear Ms. Huda, Thank you for helping me find good books. You are kind because you always smile. I love reading because of you! Do you have a favorite book? Sincerely, Noura Revise: add one more reason – I read faster now because you help me choose easy books. Edit: period, question mark, exclamation mark – check! Comma after Dear Ms. Huda and Sincerely – check! Publish: Noura puts the letter in an envelope and delivers it. Ms. Huda smiles!"}]}],"unit_test":[{"q":"We buy bread and cakes at the ___.","answer":"bakery","explanation":"Bakeries sell bread.","explanation_ar":"المخبز.","options":["library","bakery","hospital","mosque"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"The man next door is our ___.","answer":"neighbor","explanation":"Next door = neighbor.","explanation_ar":"جار.","options":["nurse","firefighter","neighbor","doctor"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"Which word is a compound word?","answer":"playground","explanation":"play + ground.","explanation_ar":"playground.","options":["doctor","playground","market","street"],"dok":1,"skill":"compound words","_part":"Part A – Words"},{"q":"Which two words make *bedroom*?","answer":"bed + room","explanation":"bed + room.","explanation_ar":"bed + room.","options":["bed + room","be + droom","bedr + oom","bed + broom"],"dok":1,"skill":"compound words","_part":"Part A – Words"},{"q":"A ___ helps doctors and cares for sick people.","answer":"nurse","explanation":"Nurses care for the sick.","explanation_ar":"الممرضة.","options":["baker","librarian","neighbor","nurse"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"Police officers ___ our streets safe.","answer":"keep","explanation":"Keep = make stay safe.","explanation_ar":"يحافظون.","options":["keep","deliver","bake","borrow"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"The bus driver works a lot and does a great job. He is ___.","answer":"hard-working","explanation":"Hard-working.","explanation_ar":"مجتهد.","options":["heavy","sick","hard-working","near"],"dok":2,"skill":"vocabulary in context","_part":"Part A – Words"},{"q":"All the people in our town who help each other are our ___.","answer":"community","explanation":"Community.","explanation_ar":"مجتمعنا.","options":["station","statement","fire","community"],"dok":2,"skill":"vocabulary in context","_part":"Part A – Words"},{"q":"Which sentence needs a question mark?","answer":"Where is the clinic","explanation":"It asks something.","explanation_ar":"تسأل.","options":["The clinic is near","Where is the clinic","I go to the clinic","Nurses are kind"],"dok":1,"skill":"end marks","_part":"Part D – Check the sentences"},{"q":"Which question is in the right order?","answer":"Is the nurse busy?","explanation":"Is + subject + describing word.","explanation_ar":"Is + الفاعل.","options":["The nurse is busy?","Busy is the nurse?","Is the nurse busy?","Is busy the nurse?"],"dok":1,"skill":"question order","_part":"Part D – Check the sentences"},{"q":"Which thank-you sentence is correct?","answer":"Thank you for helping me.","explanation":"for + -ing.","explanation_ar":"for + ing.","options":["Thank you for helping me.","Thank you for help me.","Thank for you helping.","Thanks you for helping."],"dok":2,"skill":"usage","_part":"Part D – Check the sentences"},{"q":"Which compound word means *a room where you sleep*?","answer":"bedroom","explanation":"bed + room.","explanation_ar":"bedroom.","options":["classroom","bathroom","playroom","bedroom"],"dok":2,"skill":"compound words","_part":"Part D – Check the sentences"},{"q":"Which sentence is a strong text-to-self connection to *The Lost Library Book*?","answer":"I lost my book once, and my teacher helped me find it.","explanation":"It matches the story.","explanation_ar":"يتصل بالقصة.","options":["I like pizza.","My shoes are blue.","I lost my book once, and my teacher helped me find it.","Cats can jump."],"dok":2,"skill":"connections","_part":"Part D – Check the sentences"}],"unit_writing":{"task":"Write 5–6 sentences about your neighborhood. Name places and helpers, and include one question.","model":"I live in a friendly neighborhood in Taif. There is a mosque and a bakery near my house. The baker is hard-working because he makes bread early every day. A police officer helps us cross the street. Do you have a park in your neighborhood? I love my community!","marks":20}});
